package web.pages

import androidx.compose.runtime.Composable
import androidx.compose.runtime.MutableState
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import kotpref.models.Languages
import ui.navigation.helpers.OnBoardingPage
import ui.screens.app.AppScreenEvent
import ui.screens.app.AppScreenVM
import ui.screens.app.OnboardingPagesRoute
import ui.screens.onboarding.age.OnBoardingAgeEvent
import ui.screens.onboarding.compatibility.OnBoardingCompatibilityEvent
import ui.screens.onboarding.compatibilityAnswers.OnBoardingCompatibilityAnswersEvent
import ui.screens.onboarding.finish.OnBoardingFinishEvent
import ui.screens.onboarding.paywall.PaywallScreenEvent
import ui.screens.onboarding.start.OnBoardingStartEvent
import ui.screens.onboarding.tutorial.OnBoardingTutorialEvent
import web.screens.onboarding.JsOnBoardingCompatibilityAnswersScreen
import web.screens.onboarding.JsOnBoardingCompatibilityScreen
import web.screens.onboarding.JsOnBoardingFinishScreen
import web.screens.onboarding.JsOnBoardingStartScreen
import web.screens.onboarding.JsOnBoardingTutorialScreen
import web.screens.onboarding.OnBoardingAgeScreen
import web.screens.onboarding.paywall.JsPaywallScreen


@Composable
internal fun OnboardingPagesNavigation(
    viewModel: AppScreenVM,
    obtainEvent: (AppScreenEvent) -> Unit
) {
    var startScreen: OnboardingPagesRoute = OnboardingPagesRoute.SelectGenderScreen
    val currentPage = viewModel.appKeys.onboardingCurrentPage
    if (currentPage >= OnBoardingPage.INTERESTS.ordinal) {
        startScreen = OnboardingPagesRoute.Compatibility
    }
    val currentState: MutableState<OnboardingPagesRoute> = remember { mutableStateOf(startScreen) }

    when (currentState.value) {
        OnboardingPagesRoute.SelectGenderScreen -> JsOnBoardingStartScreen(
            true,
            viewModelCallback = {
                when (it) {
                    OnBoardingStartEvent.Back -> {}
                    is OnBoardingStartEvent.ClearData -> obtainEvent(AppScreenEvent.ShowStartPages)
                    OnBoardingStartEvent.OnBoardingGenderInfo -> {}
                    OnBoardingStartEvent.OnBoardingNextPage ->
                        currentState.value = OnboardingPagesRoute.SelectInterestedGenderScreen

                    OnBoardingStartEvent.ShowMainPage -> obtainEvent(AppScreenEvent.ShowMainPages)
                }
            })

        OnboardingPagesRoute.SelectInterestedGenderScreen -> JsOnBoardingStartScreen(
            false,
            viewModelCallback = {
                when (it) {
                    OnBoardingStartEvent.Back ->
                        currentState.value = OnboardingPagesRoute.SelectGenderScreen

                    is OnBoardingStartEvent.ClearData -> {}
                    OnBoardingStartEvent.OnBoardingGenderInfo -> {}
                    OnBoardingStartEvent.OnBoardingNextPage ->
                        currentState.value = OnboardingPagesRoute.AgeScreen

                    OnBoardingStartEvent.ShowMainPage -> obtainEvent(AppScreenEvent.ShowMainPages)
                }
            })

        OnboardingPagesRoute.AgeScreen -> OnBoardingAgeScreen(viewModelCallback = {
            when (it) {
                OnBoardingAgeEvent.Back ->
                    currentState.value = OnboardingPagesRoute.SelectGenderScreen
                is OnBoardingAgeEvent.LoadPeopleSuccess -> {}
                is OnBoardingAgeEvent.LocationPermission -> {}
                OnBoardingAgeEvent.OnBoardingNextPage ->
                    currentState.value = OnboardingPagesRoute.Compatibility
            }
        })

        is OnboardingPagesRoute.Interest -> {}
        is OnboardingPagesRoute.PhotosSelect -> {}

        OnboardingPagesRoute.Tutorial -> {
            viewModel.appKeys.onboardingCurrentPage = OnBoardingPage.TUTORIAL.ordinal
            JsOnBoardingTutorialScreen(
                false, viewModelCallback = {
                    when (it) {
                        OnBoardingTutorialEvent.Back -> {}
                        OnBoardingTutorialEvent.OnBoardingNextPage ->
                            currentState.value = OnboardingPagesRoute.Finish

                        is OnBoardingTutorialEvent.ShowMainPage -> obtainEvent(AppScreenEvent.ShowMainPages)
                        is OnBoardingTutorialEvent.SubscribePropose -> {}
                    }
                }
            )
        }

        OnboardingPagesRoute.Compatibility -> {
            viewModel.appKeys.onboardingCurrentPage = OnBoardingPage.COMPATIBILITY.ordinal
            JsOnBoardingCompatibilityScreen(
                viewModelCallback = {
                    when (it) {
                        OnBoardingCompatibilityEvent.Back ->
                            currentState.value = OnboardingPagesRoute.AgeScreen

                        OnBoardingCompatibilityEvent.OnBoardingNextPage ->
                            currentState.value = OnboardingPagesRoute.CompatibilityAnswers

                        OnBoardingCompatibilityEvent.ProfileCompatibilityAnswers ->
                            currentState.value = OnboardingPagesRoute.CompatibilityAnswers

                        OnBoardingCompatibilityEvent.SkipCompatibility ->
                            currentState.value = OnboardingPagesRoute.Tutorial
                    }
                }
            )
        }


        OnboardingPagesRoute.CompatibilityAnswers -> JsOnBoardingCompatibilityAnswersScreen(
            Languages.ENGLISH.locale,
            viewModelCallback = {
                when (it) {
                    OnBoardingCompatibilityAnswersEvent.Back ->
                        currentState.value = OnboardingPagesRoute.Compatibility

                    is OnBoardingCompatibilityAnswersEvent.LoadPeopleSuccess -> {}
                    OnBoardingCompatibilityAnswersEvent.OnBoardingFinish ->
                        currentState.value = OnboardingPagesRoute.Finish
                }
            }
        )

        OnboardingPagesRoute.Finish -> JsOnBoardingFinishScreen(
            viewModelCallback = {
                when (it) {
//                        OnBoardingFinishEvent.Back -> navController.popBackStack()
                    is OnBoardingFinishEvent.GpsAccess -> it.onAccess(true)
                    is OnBoardingFinishEvent.LoadPeopleSuccess -> {}
                    is OnBoardingFinishEvent.LocationAccess -> it.onAccess(true)
                    OnBoardingFinishEvent.OnBoardingNextPage ->
                        currentState.value = OnboardingPagesRoute.Paywall

                    OnBoardingFinishEvent.OnBoardingTutorial ->
                        currentState.value = OnboardingPagesRoute.Tutorial

                    is OnBoardingFinishEvent.ShowMainPage -> obtainEvent(AppScreenEvent.ShowMainPages)
                    OnBoardingFinishEvent.SplashStart -> obtainEvent(AppScreenEvent.ShowStartPages)
                    OnBoardingFinishEvent.SubscribePropose -> {}
                }
            }
        )

        OnboardingPagesRoute.Paywall -> JsPaywallScreen(
            viewModelCallback = {
                when (it) {
                    is PaywallScreenEvent.ShowMainPage -> obtainEvent(AppScreenEvent.ShowMainPages)
                }
            }
        )
    }
}