@Composable
fun JsSplashSignInScreen(
    obtainEvent: (SplashSignInByEmailScreenEvent) -> Unit
) {

    val viewModel = rememberJsViewModel {
        SplashSignInByEmailVM(
            "", "", authorizationType = AuthorizationType.EMAIL, obtainEvent
        )
    }


    PageColumnContainer {
        JsCustomTabBar(
            onBack = { obtainEvent(SplashSignInByEmailScreenEvent.OnBackClick) },
            withBackground = false
        )

        Box(modifier = Modifier.weight(0.6f).minHeight(24.dp))
        SignInStartState(viewModel)
        Box(modifier = Modifier.weight(1.4f).minHeight(24.dp))
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(bottom = 24.dp),
            horizontalArrangement = Arrangement.Center
        ) {
            JsTextView(
                text = stringResource(Res.string.auth_start_group_text),
                textColor = JsMainTheme.colors.text_color_gray,
                textSize = 15,
                fontWeight = FontWeight.Medium,
                textAlign = TextAlign.Center
            )
            JsTextView(
                text = stringResource(Res.string.auth_sign_up_title),
                modifier = Modifier
                    .padding(leftRight = 16.dp)
                    .clickable { obtainEvent(SplashSignInByEmailScreenEvent.SplashSignUp) },
                textColor = JsMainTheme.colors.app_main_color,
                textSize = 15,
                fontWeight = FontWeight.Medium,
                textAlign = TextAlign.Center
            )
        }


        Box(
            Modifier.fillMaxWidth().padding(bottom = 26.dp),
            contentAlignment = Alignment.Center
        ) {
            val emailErrorText = stringResource(Res.string.error_message_sign_in_invalid_email)
            val passwordErrorText = stringResource(Res.string.error_message_sign_password_at_least)

            SplashFiorryButton(title = stringResource(Res.string.onboarding_start_btn_text_next)) {
                val emailError = viewModel.checkEmailError(emailErrorText)
                val passwordError = viewModel.checkPasswordError(passwordErrorText)
                if (emailError || passwordError) return@SplashFiorryButton
                viewModel.continueSignIn()
            }
        }
    }

    if (viewModel.showProgress.value) LoadingBlockState()
}

@Composable
private fun SignInStartState(viewModel: SplashSignInByEmailVM) {
    Column(
        modifier = Modifier.fillMaxWidth(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Box(modifier = Modifier.height(16.dp))

        JsTextView(
            text = stringResource(Res.string.auth_sign_in),
            modifier = Modifier
                .fillMaxWidth()
                .padding(leftRight = 20.dp),
            textColor = JsMainTheme.colors.text_color_default,
            textSize = 24,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center
        )
        Box(modifier = Modifier.height(32.dp))

        JsOutlinedTextField(
            value = viewModel.emailValue.value.text,
            textSize = 14,
            textMinHeight = 50,
            label = stringResource(Res.string.auth_text_hint_email),
            isError = viewModel.emailErrorValue.value.isNotEmpty(),
            errorText = viewModel.emailErrorValue.value,
            modifier = Modifier.fillMaxWidth(80.percent)
                .onFocusIn { viewModel.emailErrorValue.value = "" },
            onValueChange = {
                viewModel.emailValue.value = TextFieldValue(it)
            }
        )

        var showPassword by remember { mutableStateOf(false) }
        JsOutlinedTextField(
            value = viewModel.passwordValue.value,
            textSize = 14,
            textMinHeight = 50,
            label = stringResource(Res.string.auth_text_hint_password),
            isError = viewModel.passwordErrorValue.value.isNotEmpty(),
            errorText = viewModel.passwordErrorValue.value,
            modifier = Modifier.fillMaxWidth(80.percent).padding(top = 12.dp)
                .onFocusIn { viewModel.passwordErrorValue.value = "" },
            inputType = if (showPassword) InputType.Text else InputType.Password,
            rightIcon = if (showPassword) "ic_password_visibility_off_web" else "ic_password_visibility_web",
            rightIconClick = { showPassword = !showPassword },
            onValueChange = {
                viewModel.passwordValue.value = it
            }
        )
    }
}