@Composable
fun JsOnBoardingCompatibilityAnswersScreen(
    language: String,
    viewModelCallback: (OnBoardingCompatibilityAnswersEvent) -> Unit,
    viewModel: OnboardingCompatibilityAnswersComposeVM = rememberJsViewModel {
        OnboardingCompatibilityAnswersComposeVM(language, viewModelCallback)
    }
) {
    val isLoading = viewModel.isLoading.value

    PageContainer {
        Column(Modifier.fillMaxSize(), horizontalAlignment = Alignment.CenterHorizontally) {
            Box(modifier = Modifier.fillMaxWidth()) {
                JsCustomTabBar(
                    onBack = { viewModel.back() },
                    withBackground = false,
                    isColor = false,
                    tabBarType = TabBars.TabBarWithRightButton(
                        rightButtonTitle = stringResource(resource = Res.string.onboarding_compatibility_skip),
                        rightButtonUnderline = true,
                        onRightButtonClick = { viewModel.skipCompatibility() }
                    )
                )
            }

            if (!isLoading) {
                Box(modifier = Modifier.fillMaxSize()) {
                    OnboardingCompatibilityAnswersContent(
                        viewModel = viewModel, question = viewModel.getCurrentQuestion()
                    )

                    JsAnimatedVisibility(
                        viewModel.questionState.value == QuestionState.NEXT_QUESTION,
                        animationDirection = AnimationDirection.RIGHT_TO_LEFT,
                        durationMs = viewModel.animationDuration,
                        hiddenDurationMs = 0,
                        minOpacity = 0.2f,
                        opacityAnimation = AnimationTimingFunction.Linear
                    ) {
                        OnboardingCompatibilityAnswersContent(
                            viewModel = viewModel,
                            question = viewModel.questions[viewModel.nextQuestion],
                            animationState = viewModel.questionState
                        )
                    }
                }
            }
        }
    }

    if (isLoading) LoadingState()
}

@Composable
fun OnboardingCompatibilityAnswersContent(
    viewModel: OnboardingCompatibilityAnswersComposeVM,
    question: CompatibilityQuestion,
    animationState: MutableState<QuestionState> = mutableStateOf(QuestionState.DEFAULT)
) {
    val currentResult = remember(question.id) {
        mutableStateOf(viewModel.answers[question.id] ?: CompatibilityAnswerStatus.NoSelect)
    }

    val screenWidth = getJsScreenSizeInfo().widthPx

    Box(
        modifier = Modifier
            .fillMaxHeight()
            .width(screenWidth.px)
            .fillMaxWidth()
    ) {
        Column(
            Modifier
                .fillMaxSize()
                .background(JsMainTheme.colors.main_color_background),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            CategoryAnswer(viewModel, question, parentScope = this, currentResult) { answer ->
                if (
                    viewModel.chooseAnswer || viewModel.startAnimation ||
                    DateTimeConverter.currentTimeMillis() - viewModel.lastTimeAnimationFinish < viewModel.animationDuration
                ) return@CategoryAnswer

                viewModel.chooseAnswer = true
                viewModel.answers[question.id] = answer
                currentResult.value = answer

                viewModel.showChooseCompatibility()
            }

            JsAutoResizeText(
                text = stringResource(resource = Res.string.onboarding_compatibility_text_answers),
                maxTextSize = 15,
                minTextSize = 8,
                modifier = Modifier
                    .fillMaxWidth(0.9f.toPercent())
                    .padding(top = 12.dp, bottom = 28.dp)
                    .alpha(0.75f),
                color = Color.rgb(0XB46BEE).copy(alpha = 0.5f),
                textAlign = TextAlign.Center,
                maxLines = 2
            )
        }
    }

    LaunchedEffect(animationState.value) {
        if (animationState.value == QuestionState.NEXT_QUESTION) {
            delay(viewModel.animationDuration)
            viewModel.finishAnimation()
            viewModel.currentQuestion++
            animationState.value = QuestionState.DEFAULT
        } else if (animationState.value == QuestionState.PREVIOUS_QUESTION) {
            viewModel.finishAnimation()
            animationState.value = QuestionState.DEFAULT
        }
    }
}

@Composable
private fun CategoryAnswer(
    viewModel: OnboardingCompatibilityAnswersComposeVM,
    question: CompatibilityQuestion,
    parentScope: ColumnScope,
    currentResult: MutableState<CompatibilityAnswerStatus>,
    onChangeAnswer: (CompatibilityAnswerStatus) -> Unit
) {
    val drawableId: DrawableResource
    val text: String
    when (question.group) {
        CompatibilityCategory.Lifestyle.group, CompatibilityCategory.Libido.group -> {
            drawableId = Res.drawable.ic_compatibility_category_lifestyle
            text = stringResource(resource = Res.string.people_profile_compatibility_lifestyle)
        }

        CompatibilityCategory.Sexual.group -> {
            drawableId = Res.drawable.ic_compatibility_category_sexual
            text = stringResource(resource = Res.string.people_profile_compatibility_sexual)
        }

        CompatibilityCategory.Mindset.group -> {
            drawableId = Res.drawable.ic_compatibility_category_mindset
            text = stringResource(resource = Res.string.people_profile_compatibility_mindset)
        }

        CompatibilityCategory.Habits.group, CompatibilityCategory.Extreme.group -> {
            drawableId = Res.drawable.ic_compatibility_category_habits
            text = stringResource(resource = Res.string.people_profile_compatibility_habits)
        }

        else -> {
            drawableId = Res.drawable.ic_compatibility_category_goals
            text = stringResource(resource = Res.string.people_profile_compatibility_goals)
        }
    }
    Box(
        Modifier.fillMaxWidth(),
        contentAlignment = Alignment.Center
    ) {
        JsImageView(
            drawableRes = drawableId,
            modifier = Modifier
                .fillMaxWidth(0.25f.toPercent())
                .heightIn(max = (resultHeight.value * 0.25f).px),
            contentScale = ContentScale.FillBounds
        )
    }

    val textColor = JsMainTheme.colors.main_color_bg_3

    val currentStepModifier = Modifier.styleModifier {
        color(textColor)
    }
    val currentCount = (viewModel.currentQuestion + 1).toString()
    val annotatedString = listOf(
        AnnotatedString(stringResource(Res.string.onboarding_compatibility_question), null),
        AnnotatedString(" $currentCount/${viewModel.questions.size}", currentStepModifier)
    )
    JsTextView(
        text = text,
        textSize = 16,
        textColor = JsMainTheme.colors.text_color_default,
        modifier = Modifier.padding(top = 12.dp),
        fontWeight = FontWeight.Medium
    )
    JsAnnotatedStringsText(
        annotatedStrings = annotatedString,
        modifier = Modifier.padding(top = 4.dp),
        textSize = 16,
        textColor = JsMainTheme.colors.text_color_default,
        fontWeight = FontWeight.Medium
    )


    parentScope.run {
        Column(
            Modifier.weight(1f).fillMaxWidth(),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            val verticalBias = 0.25f
            Box(Modifier.weight(verticalBias))
            Column(
                Modifier.fillMaxWidth(0.7f.toPercent()),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                val language = viewModel.language
                val questionText = Languages.getQuestionText(language, question)
                JsTextView(
                    text = questionText
                        ?: stringResource(resource = Res.string.onboarding_compatibility_title),
                    textAlign = TextAlign.Center, fontWeight = FontWeight.Bold, textSize = 24
                )

                SetAnswer(
                    question.group, question.positiveAnswer, language,
                    stringResource(resource = Res.string.dialog_btn_yes),
                    isSelected = currentResult.value == CompatibilityAnswerStatus.Yes,
                    onClick = { onChangeAnswer(CompatibilityAnswerStatus.Yes) },
                    iconDefault = Res.drawable.ic_onboarding_select_accept
                )

                SetAnswer(
                    question.group, question.negativeAnswer, language,
                    stringResource(resource = Res.string.dialog_btn_no),
                    isSelected = currentResult.value == CompatibilityAnswerStatus.No,
                    onClick = { onChangeAnswer(CompatibilityAnswerStatus.No) },
                    iconDefault = Res.drawable.ic_close_white_24dp
                )

                SetAnswer(
                    question.group, question.presumptiveAnswer, language,
                    stringResource(resource = Res.string.onboarding_compatibility_maybe),
                    isSelected = currentResult.value == CompatibilityAnswerStatus.Maybe,
                    onClick = { onChangeAnswer(CompatibilityAnswerStatus.Maybe) }
                )
            }
            Box(Modifier.weight(1f - verticalBias))
        }
    }
}

@Composable
private fun SetAnswer(
    category: String?,
    answer: CompatibilityQuestionAnswer?,
    language: String,
    textDefault: String,
    isSelected: Boolean,
    onClick: () -> Unit,
    iconDefault: DrawableResource? = null
) {
    val buttonText = if (answer == null) textDefault
    else Languages.getAnswerText(language, answer) ?: textDefault

    val color = getCategoryColor(category, isSelected)

    val modifier = if (isSelected) Modifier.clipByCorner().background(color).padding(all = 1.dp)
    else Modifier.clipByCorner().border(1.dp, style = LineStyle.Solid, Color.rgb(0X9CADBA))

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .padding(start = 16.dp, top = 24.dp, end = 16.dp)
    ) {
        Box(
            contentAlignment = Alignment.Center,
            modifier = modifier
                .fillMaxWidth()
                .clickable { onClick.invoke() }
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                JsTextView(
                    text = buttonText,
                    textSize = 16,
                    fontWeight = FontWeight.Medium,
                    modifier = Modifier.padding(horizontal = 14.dp, vertical = 12.dp)
                )
                if (buttonText == textDefault && iconDefault != null)
                    JsImageView(
                        iconDefault,
                        modifier = Modifier.size(24.dp)
                    )
            }
        }
    }
}

@Composable
private fun getCategoryColor(category: String?, isSelect: Boolean = false): Color {
    val color = when (category) {
        CompatibilityCategory.Goals.group -> JsMainTheme.colors.gradient_compatibility_category_goals_start
        CompatibilityCategory.Sexual.group -> JsMainTheme.colors.gradient_compatibility_category_sexual_start
        CompatibilityCategory.Mindset.group -> JsMainTheme.colors.gradient_compatibility_category_mindset_end
        CompatibilityCategory.Habits.group -> JsMainTheme.colors.gradient_compatibility_category_habits_start
        CompatibilityCategory.Extreme.group -> JsMainTheme.colors.gradient_compatibility_category_habits_start
        else -> JsMainTheme.colors.gradient_compatibility_category_lifestyle_start
    }
    return color.copy(alpha = if (isSelect) 0.85f else 0.5f)
}