//@Entity
@kotlinx.serialization.Serializable
data class LastMessageChatUser(

    //@ColumnInfo(name = "last_message_chat_user_id")
    @SerialName("id") val id: String = "",

    //@ColumnInfo(name = "last_message_chat_user_name")
    @SerialName("name") val name: String = "",

    //@ColumnInfo(name = "last_message_chat_user_avatar")
    @SerialName("avatar") val avatar: String? = null,

    //@ColumnInfo(name = "last_message_chat_user_online")
    @SerialName("isOnline") var isOnline: Boolean = false,

    //@ColumnInfo(name = "last_message_chat_user_verification")
    @SerialName("photo_verification_status") var photoVerificationStatus: String? = null

) {

    fun toUser(): ChatUser = ChatUser(id, name, avatar, isOnline, photoVerificationStatus, "")
}
