package web.screens.onboarding

import androidx.compose.runtime.Composable
import com.varabyte.kobweb.compose.ui.graphics.Color
import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.onboarding_finish_btn
import org.jetbrains.compose.resources.DrawableResource
import ui.screens.onboarding.finish.OnBoardingFinishEvent
import ui.screens.onboarding.finish.OnBoardingFinishVM
import web.helpers.rememberJsViewModel
import web.helpers.stringResource
import web.views.OnBoardingDefaultBox
import web.views.PageContainer

@Composable
fun JsOnBoardingFinishScreen(
    viewModelCallback: (OnBoardingFinishEvent) -> Unit,
    viewModel: OnBoardingFinishVM = rememberJsViewModel {
        OnBoardingFinishVM(viewModelCallback)
    }
) {
    val image: DrawableResource = viewModel.getPageBackgroundImage()

    PageContainer {
        OnBoardingDefaultBox(
            image = image,
            title = stringResource(resource = viewModel.mainTitle),
            text = stringResource(resource = viewModel.text),
            textColor = Color.rgb(0X9CADBA),
            buttonText = stringResource(resource = Res.string.onboarding_finish_btn),
            mainButtonClick = { viewModel.clickedBtn() }
        )
    }

}