package managers

import kotpref.models.EDialogType
import kotpref.utils.IDialogManager
import org.jetbrains.compose.resources.StringResource

class WebDialogManager: IDialogManager {

    override var showDialog: (ShowAlertState) -> Unit = { _ -> }

    override fun showMessageDialog(message: String) {
        showDialog(ShowAlertState.ShowDefaultDialog("", message))
    }

    override fun showMessageDialog(message: StringResource) {
        showDialog(ShowAlertState.ShowDefaultDialog("", message))
    }

    override fun showMessageDialog(
        mesType: EDialogType,
        callback: () -> Unit,
        onCancel: () -> Unit,
        title: String,
        dialogText: String,
        hint: String,
        btnOk: String,
        btnCancel: String
    ) {
        val alertState = when (mesType) {
            EDialogType.DIALOG_DELETE_ACCOUNT_ONBOARDING -> AlertType.DeleteAccount
            else -> AlertType.Default
        }
        showDialog(
            ShowAlertState.AlertByType(alertState, onOkClick = callback, onCancelClick = onCancel)
        )
    }

    override fun showMessageWithTitleDialog(
        title: String,
        message: String,
        callback: () -> Unit,
        isLastDialog: Boolean
    ) {
        showDialog(
            ShowAlertState.ShowOkCancelDialog(
                title = title,
                message = message,
                okText = "",
                cancelText = null,
                dismissOnClickOutside = true,
                onOkClick = callback
            )
        )
    }

    override fun hasDialog(): Boolean {
        return false
    }

    override fun haveLocationDialog(): Boolean {
        return false
    }

    override fun dismissDialog() {

    }

    override fun dismissStartDialogs() {

    }

    override fun setNetworkSession(networkSession: Any) {

    }

    override fun getNetworkSession(): Any? {
        return null
    }

    override fun resetManager() {

    }
}