package dependencies

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotpref.models.account.AccountPhoto
import kotpref.stores.IAppKeysStorage
import kotpref.utils.IAppKeysSecureDefault
import network.restApi.requests.ChatRequests
import network.restApi.requests.FileRequests

class FileRepository(
    private val fileRequests: FileRequests,
    private val chatRequests: ChatRequests,
    private val accountRepository: AccountRepository,
    private val appKeysSecureDefault: IAppKeysSecureDefault

) {

    fun getAppKeys(): IAppKeysStorage {
        return fileRequests.appKeys
    }

    ///region Server
    fun uploadPhotoByPath(
        filePath: String,
//        listener: ProgressRequestBody.UploadCallbacks? = null,
        onSuccess: (AccountPhoto?) -> Unit,
        onModerateError: (String) -> Unit = {},
        onError: (String?) -> Unit = {}
    ) {
        val moderateApiUser = appKeysSecureDefault.moderateApiUser
        val moderateApiSecret = appKeysSecureDefault.moderateApiSecret
        fileRequests.uploadPhoto(filePath, /*listener,*/moderateApiUser, moderateApiSecret,
            onSuccess = { CoroutineScope(Dispatchers.Main).launch { onSuccess(it?.data) } },
            onModerateError = { CoroutineScope(Dispatchers.Main).launch { onModerateError(it) } },
            onError = { CoroutineScope(Dispatchers.Main).launch { onError(it) } })
    }

    fun stopUploadPhoto() {
        fileRequests.stopUploadPhoto()
    }

    fun uploadAvatar(
        filePath: String, fromProfile: Boolean,
//        listener: ProgressRequestBody.UploadCallbacks? = null,
        onSuccess: (String?) -> Unit, onError: (String?) -> Unit = {}
    ) {
        fileRequests.uploadAvatar(filePath, /*listener,*/ onSuccess = {
            if (getAppKeys().userRegistered) chatRequests.reconnectWebSocket()
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
//                if (fromProfile) accountRepository.saveAccountWithoutMerge(it?.data)
//                else {
//                    val account = accountRepository.getMyAccount()
//                    account?.avatar = it?.data?.avatar
//                    account?.photos = it?.data?.photos
//                    accountRepository.saveAccount(account)
//                }
                CoroutineScope(Dispatchers.Main).launch { onSuccess(it?.data?.avatar) }
            }
        }, onError = { CoroutineScope(Dispatchers.Main).launch { onError(it) } })
    }

    fun deleteAvatar(
        deleteFromOnboarding: Boolean = false,
        onSuccess: () -> Unit = {}, onError: (String?) -> Unit = {}
    ) {
        fileRequests.deleteAvatar(onSuccess = {
            val account = it?.account
            account?.avatar = ""
            account?.photos = mutableListOf()
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
//                if (deleteFromOnboarding) accountRepository.saveAccount(account)
//                else accountRepository.saveAccountWithoutMerge(account)

                CoroutineScope(Dispatchers.Main).launch { onSuccess() }
            }
        }, onError = { CoroutineScope(Dispatchers.Main).launch { onError(it) } })
    }

    fun syncPhotos(
        photos: MutableList<AccountPhoto>, fromProfile: Boolean,
        onSuccess: () -> Unit, onError: (String?) -> Unit = {}
    ) {
        fileRequests.syncPhotos(photos, onSuccess = {
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
//                if (fromProfile) accountRepository.saveAccountWithoutMerge(it?.data)
//                else {
//                    val account = accountRepository.getMyAccount()
//                    account?.avatar = it?.data?.avatar
//                    account?.photos = it?.data?.photos
//                    accountRepository.saveAccount(account)
//                }
                CoroutineScope(Dispatchers.Main).launch { onSuccess() }
            }
        }, onError = { CoroutineScope(Dispatchers.Main).launch { onError(it) } })
    }

    fun deletePhoto(photoId: String, onSuccess: () -> Unit, onError: (String?) -> Unit = {}) {
        fileRequests.deletePhoto(photoId, onSuccess = {
            CoroutineScope(Dispatchers.Main).launch { onSuccess() }
        }, onError = { CoroutineScope(Dispatchers.Main).launch { onError(it) } })
    }
    ///endregion

    ///region Database

    ///endregion
}