package kotpref.models.typeConverter

import kotpref.utils.IPlatformInfoManager
import kotpref.models.MessageResult
import kotpref.models.account.Account
import kotpref.models.chat.ChatDialog
import kotpref.models.chat.ChatImage
import kotpref.models.chat.ChatMessage
import fiori.transgender.ui.kotpref.models.chat.ChatMessageItem
import kotpref.models.chat.ChatMessageStatus
import fiori.transgender.ui.kotpref.models.chat.ChatRoom
import kotpref.models.chat.ChatUser

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-22.
 */
class ChatConverter(
    val platformManager: IPlatformInfoManager
) {

    fun convertToDialog(
        chats: MutableList<ChatRoom>?, myAccountId: String
    ): MutableList<ChatDialog> {
        val dialogs = mutableListOf<ChatDialog>()
        if (chats?.size == 0) return dialogs
        chats?.forEach {
            val dialog = convertRoomToDialog(it, myAccountId)
            if (dialog != null) dialogs.add(dialog)
        }
        return dialogs
    }

    private fun convertMessageToItem(
        message: ChatMessage?,
        chatUser: ChatUser?,
        updateBody: Boolean = true,
        fromServer: Boolean = false
    ): ChatMessageItem? {
        if (message == null || chatUser == null) return null
        val status = if (message.isRead) ChatMessageStatus.READ else ChatMessageStatus.SENT

        val text = if (message.type != 1 && updateBody) null else message.body
//        val deleteAt = if (fromServer) DateTimeConverter.getTime(message.deleteAt)
//        else DateTimeConverter.stringToDate(message.deleteAt)
        val image: ChatImage? = when {
            message.type == 4 -> ChatImage(message.body)
            message.type != 1 -> ChatImage(
                message.photo?.url ?: "",
                message.photo?.height ?: 0,
                message.photo?.width ?: 0,
                lifetime = message.lifetime,
                deleteAt = message.deleteAt
            )
            else -> null
        }
        val chatMessage = ChatMessageItem(
            message.uuid, chatUser, text, message.type,
            message.createdAt, status, status.resId(), false, image
        )
        return chatMessage
    }

    fun convertTextToMessageItem(
        message: String, chatRoom: ChatDialog, senderId: String
    ): ChatMessageItem? {
        val chatUser = convertDialogToUser(chatRoom.chatUsers, senderId)
        return convertTextToMessageItem(message, chatUser)
    }

    fun convertTextToMessageItem(
        message: String, chatUser: ChatUser?
    ): ChatMessageItem? {
        if (chatUser == null) return null
        val chatMessage = ChatMessageItem(
            platformManager.getUUIDString(), chatUser, message, 1, DateTimeConverterPlatform.getTimeZoneDateString(),
            ChatMessageStatus.SENDING
        )
        return chatMessage
    }

    fun convertUrlToMessageItem(
        url: String, chatRoom: ChatDialog, senderId: String, lifeTime: Int?
    ): ChatMessageItem? {
        val chatUser = convertDialogToUser(chatRoom.chatUsers, senderId)
        return convertUrlToMessageItem(url, chatUser, senderId, lifeTime)
    }

    fun convertUrlToMessageItem(
        url: String, chatUser: ChatUser?, senderId: String, lifeTime: Int?
    ): ChatMessageItem? {
        if (chatUser == null) return null
        val chatMessage = ChatMessageItem(
            platformManager.getUUIDString(),
            chatUser,
            null,
            if (lifeTime != null) 3 else 2,
            DateTimeConverterPlatform.getTimeZoneDateString(),
            ChatMessageStatus.SENDING,
            ChatMessageStatus.SENDING.resId(),
            false,
            ChatImage(url, lifetime = lifeTime)
        )
        return chatMessage
    }

    fun convertMessageResultToItem(
        message: MessageResult, chatRoom: ChatDialog
    ): ChatMessageItem? {
        val chatUser = convertDialogToUser(chatRoom.chatUsers, message.senderId?.toString() ?: "")
        return convertMessageResultToItem(message, chatUser)
    }

    fun convertMessageResultToItem(
        message: MessageResult, chatUser: ChatUser?
    ): ChatMessageItem? {
        if (chatUser == null) return null
        val text = if (message.type != 1) null else message.body
        val image: ChatImage? =
            if (message.type != 1) message.body?.let {
                ChatImage(
                    it, lifetime = message.lifetime,
                    width = message.photo?.width ?: 0, height = message.photo?.height ?: 0
                )
            } else null
        val chatMessage = ChatMessageItem(
            message.uuid ?: platformManager.getUUIDString(), chatUser, text, message.type ?: 1,
            DateTimeConverterPlatform.getTimeZoneDateString(), ChatMessageStatus.SENT,
            ChatMessageStatus.SENT.resId(), false, image
        )
        return chatMessage
    }

    private fun convertRoomToUser(chatRoom: ChatRoom, myAccountId: String = ""): ChatUser? {
        if (chatRoom.accounts.isNullOrEmpty()) return null
        var user = chatRoom.accounts?.get(0)
        chatRoom.accounts?.forEach { if (it.id != myAccountId) user = it }
        return convertAccountToUser(user)
    }

    fun convertAccountToUser(user: Account?): ChatUser {
        return ChatUser(
            user?.id ?: "", user?.nickname ?: "", user?.avatar ?: "",
            user?.isOnline ?: false, user?.photoVerificationStatus?: "" ,user?.lastActive ?: ""
        )
    }

    private fun convertRoomToUsers(chatRoom: ChatRoom): ArrayList<ChatUser> {
        val users = ArrayList<ChatUser>()
        chatRoom.accounts?.forEach { users.add(convertAccountToUser(it)) }
        return users
    }

    private fun convertDialogToUser(
        chatUsers: MutableList<ChatUser>, senderId: String = ""
    ): ChatUser? {
        if (chatUsers.size == 0) return null
        var chat = chatUsers[0]
        chatUsers.forEach { if (it.getId() == senderId) chat = it }
        return chat
    }

    fun createMyUser(sender: Account?): ChatUser {
        val chatUser = ChatUser(
            sender?.id ?: "", sender?.nickname ?: "", sender?.avatar ?: "",
            true, sender?.photoVerificationStatus?: "" ,sender?.lastActive ?: ""
        )
        return chatUser
    }

    fun convertRoomToDialog(chatRoom: ChatRoom, myAccountId: String): ChatDialog? {
        val chatUser = convertRoomToUser(chatRoom, myAccountId) ?: return null
        val body = if (chatRoom.type != 1) "Photo" else chatRoom.message ?: ""
        val lastMessage =
            ChatMessage(body = body, type = chatRoom.type ?: 1, createdAt = chatRoom.updatedAt)
        val lastMessageItem = convertMessageToItem(lastMessage, chatUser, false)

        val chatUsers = convertRoomToUsers(chatRoom)

        return ChatDialog(
            chatRoom.id.toString(), chatUser.getName(), chatUser.getAvatar() ?: "",
            chatRoom.count ?: 0, chatRoom.mode ?: 0, chatRoom.isPinned ?: false,
            chatRoom.isRequest ?: false, chatUsers, lastMessageItem?.toLast(), null
        )
    }

    fun convertMessagesToItems(
        messages: MutableList<ChatMessage>?, chatUsers: MutableList<ChatUser>,
        fromServer: Boolean = false
    ): MutableList<ChatMessageItem> {
        val chatMessages = mutableListOf<ChatMessageItem>()
        messages?.forEach {
            convertMessageToItem(
                it, convertDialogToUser(chatUsers, it.sender), fromServer = fromServer
            )?.let { message -> chatMessages.add(message) }
        }
        return chatMessages
    }

    fun convertMessageItemToChatMessage(
        messageText: String, messageItem: ChatMessageItem?
    ): ChatMessage {
        val message = ChatMessage()
        message.body = messageText
        messageItem?.let {
            message.uuid = it.getId()
            message.type = it.type
            message.status = it.status
            message.isRead = it.status == ChatMessageStatus.READ
            message.photo?.url = it.image?.url ?: ""
            message.photo?.height = it.image?.height
            message.photo?.width = it.image?.width
            message.lifetime = it.image?.lifetime
            message.deleteAt = it.image?.deleteAt
        }
        return message
    }
}