package network.restApi

import kotpref.models.AppVariant

class Endpoint {

    var scheme: String = "https"
    var port: Int? = null

    val servers = getServersDefault()

    companion object {

        const val local: Boolean = false

        val version = "3.5"  //BuildConfig.MAIN_APP_VERSION

        private val siteUrl: () -> String = {
            if (AppVariant.isFiorry()) "fiorry.co"
            else if (AppVariant.isHeaven()) "heavenapp.co"
            else if (AppVariant.isParadiz()) "paradiz.app"
            else "elizium.co"
        }

        fun getSupportUrl() = "https://${siteUrl()}/contact-us"
        fun getTermsUrl() = "https://${siteUrl()}/terms-conditions"
        fun getPrivacyPolicyUrl() = "https://${siteUrl()}/privacy-policy"
        fun getFundingUrl() = "https://${siteUrl()}/funding"
        fun getBehaviourUrl() = "https://${siteUrl()}/behavior-policies"
        fun getSupportEmail() =
            if (AppVariant.isFiorry()) "support@fiorry.co" else if (AppVariant.isElizium()) "info@dream-tek.io" else "support@paradiz.app"

        fun getStoreUrl() =
            if (AppVariant.isFiorry()) "https://fiorry.app/sWiX/ivr8vhwa"
            else if (AppVariant.isElizium()) "https://elizium.app/r2KT/34elnrgk"
            else if (AppVariant.isHeaven()) "https://heavenapp.click/bFSv/b2ceryce"
            else "https://paradiz.online/O5mM/7q1ti3h2"

        fun getStoreDeepLink() =
            if (AppVariant.isFiorry()) "https://fiorry.app/sWiX/"
            else if (AppVariant.isElizium()) "https://elizium.app/r2KT/"
            else if (AppVariant.isHeaven()) "https://heavenapp.click/bFSv/"
            else "https://paradiz.online/O5mM/"
    }

    override fun toString(): String {
        var serverUrl = "$scheme://${servers.backend}"
        port?.let { serverUrl += ":$it" }
        return serverUrl
    }

    fun moderationUrl(): String = "https://api.sightengine.com/1.0"
    fun loggerUrl(): String = "https://logs.fiori.co/"
    fun stripeUrl(): String = "https://api.stripe.com/v1/"
    fun socketUrl(): String = "wss://${servers.socket}/ws"
    fun subscribeUrl(): String = "https://${servers.subscribe}/1.0"

    private fun getServersDefault(): Servers {
        return when {
            local && AppVariant.isDebug() -> getLocalServers()
            AppVariant.isFiorry() -> if (AppVariant.isDev()) getFiorryDevServers() else getFiorryServers()
            AppVariant.isHeaven() -> if (AppVariant.isDev()) getHeavenDevServers() else getHeavenServers()
            AppVariant.isParadiz() -> if (AppVariant.isDev()) getParadizDevServers() else getParadizServers()
            else -> if (AppVariant.isDev()) getEliziumDevServers() else getEliziumServers()
        }
    }

    private fun getFiorryServers(): Servers = Servers(
        "core.fiorry.co",
        "chat.fiorry.co",
        "subs.fiorry.co"
    )

    private fun getFiorryDevServers() = Servers(
        "core.fiorry.dev",
        "chat.fiorry.dev",
        "subs.fiorry.dev"
    )

    private fun getEliziumServers() = Servers(
        "core.kyivdate.com.ua",
        "chat.kyivdate.com.ua",
        "subs.kyivdate.com.ua"
    )

    private fun getEliziumDevServers() = Servers(
        "core.kyivdate-stage.com.ua",
        "chat.kyivdate-stage.com.ua",
        "subs.kyivdate-stage.com.ua"
    )

    private fun getHeavenServers() = Servers(
        "core.heavenapp.co",
        "chat.heavenapp.co",
        "subs.heavenapp.co"
    )

    private fun getHeavenDevServers() = Servers(
        "core.heavenapp.dev",
        "chat.heavenapp.dev",
        "subs.heavenapp.dev"
    )

    private fun getParadizServers() = Servers(
        "core.paradiz.app",
        "chat.paradiz.app",
        "subs.paradiz.app"
    )

    private fun getParadizDevServers() = Servers(
        "core.paradiz.dev",
        "chat.paradiz.dev",
        "subs.paradiz.dev"
    )

    private fun getLocalServers() = Servers(
        "core-fiorry.ngrok.io",
        "chat-fiorry.ngrok.io",
        "subs-fiorry.ngrok.io"
    )


    data class Servers(val backend: String, val socket: String, val subscribe: String) {
        fun getServerList(): MutableList<String> = mutableListOf(backend, socket, subscribe)
    }
}