@Composable
fun DownloadAppScreen(clearData: () -> Unit) {
    val appKeys by di.instance<IAppKeysStorage>()
    val repositoriesProvider by di.instance<RepositoriesProvider>()
    val accountRepository = repositoriesProvider.accountRepository
    appKeys.userRegistered = true
    val passwordValue = appKeys.webRegisterPassword
    val subscribeSuccess = remember { mutableStateOf(false) }
    val showLoading = remember { mutableStateOf(true) }
    val scope = rememberCoroutineScope()

    fun deleteAccount() {
        scope.launch(Dispatchers.Main) { /* runBlocking */
            accountRepository.deleteAccount(onSuccess = {
                repositoriesProvider.database.clearDatabase()
                appKeys.userBirthday = 0L
                appKeys.startOnboarding = false
                appKeys.userRegistered = false
                appKeys.onboardingCurrentPage = 0
                appKeys.webRegisterPassword = ""
                clearData()
            }, onError = {

            }, reason = 1)
        }
    }

    LaunchedEffect(Unit) {
        val account = accountRepository.getMyAccount()
        subscribeSuccess.value = account?.subscriptionStatus?.subscription?.type != 0
        showLoading.value = false
    }

    Column(
        Modifier.fillMaxSize().overflow(Overflow.Auto),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Spacer(Modifier.size(20.dp))

        if (AppVariant.isDebug()) {
            Box(
                contentAlignment = Alignment.CenterStart,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(56.dp)
                    .clickable { deleteAccount() }
            ) {
                JsTextView(
                    stringResource(resource = Res.string.dialog_btn_delete), textSize = 15,
                    textColor = JsMainTheme.colors.app_main_color,
                    fontWeight = FontWeight.Normal,
                    modifier = Modifier.padding(all = 16.dp).fillMaxHeight()
                )
            }
        }

        Box(
            Modifier.fillMaxWidth().padding(all = 20.dp).clipByCorner(10)
                .background(Color.rgb(0xF3F3F3).copy(alpha = 0.06f)),
            contentAlignment = Alignment.Center
        ) {
            Box(Modifier.padding(all = 6.dp)) {
                JsImageView("ic_logo_fiorry_web", modifier = Modifier.height(44.dp))
            }
        }

        val icon = if (subscribeSuccess.value) "ic_main_screen_web" else "ic_account_web"
        Spacer(Modifier.size(40.dp))
        JsImageView(icon, modifier = Modifier.size(90.dp))
        Spacer(Modifier.size(30.dp))

        val title = if (subscribeSuccess.value) stringResource(Res.string.subscribe_web_successful)
        else stringResource(Res.string.web_app_account_created)
        JsTextView(
            title,
            textSize = 20,
            fontWeight = FontWeight.Bold,
            textColor = JsMainTheme.colors.text_color_white,
            textAlign = TextAlign.Center,
            modifier = Modifier.padding(horizontal = 24.dp)
        )
        Spacer(Modifier.size(20.dp))

        val text = if (subscribeSuccess.value) stringResource(Res.string.subscribe_web_to_log_in)
        else stringResource(Res.string.web_app_to_log_in)
        JsTextView(
            text,
            textSize = 20,
            textColor = JsMainTheme.colors.text_color_white,
            textAlign = TextAlign.Center,
            modifier = Modifier.padding(horizontal = 24.dp)
        )
        Spacer(Modifier.size(20.dp))

        val passwordString = stringResource(Res.string.web_app_password_generated_value)
        val fullText = stringResource(Res.string.web_app_password_generated, passwordString)
        //val textColor = JsMainTheme.colors.text_color_white

        val passwordModifier = Modifier.styleModifier {
            color(Color.rgb(0XB46BEE))
            fontWeight(FontWeight.Bold)
            whiteSpace("pre-wrap")
            overflow(Overflow.Hidden)
            textAlign(TextAlign.Center)
        }

        val passwordStartIndex = fullText.indexOf(passwordString)
        val annotatedString = listOf(
            AnnotatedString(fullText.substring(0, passwordStartIndex), null),
            AnnotatedString(
                fullText.substring(passwordStartIndex, passwordStartIndex + passwordString.length),
                passwordModifier
            ),
            AnnotatedString(
                fullText.substring(passwordStartIndex + passwordString.length), null
            ),
        )
        JsAnnotatedStringsText(
            annotatedStrings = annotatedString,
            textSize = 16,
            textColor = JsMainTheme.colors.text_color_white,
            modifier = Modifier
                .fillMaxWidth(80.percent)
                .minHeight(36.dp),
            textAlign = TextAlign.Center
        )

        JsTextView(
            passwordValue,
            textSize = 26,
            textColor = Color.rgb(0XB46BEE),
            textAlign = TextAlign.Center,
            modifier = Modifier.padding(horizontal = 24.dp, vertical = 30.dp),
            userSelect = UserSelect.Text
        )

        JsTextView(
            stringResource(Res.string.web_app_password_can_change),
            textSize = 14,
            textColor = JsMainTheme.colors.text_color_white.copy(0.5f),
            textAlign = TextAlign.Center,
            modifier = Modifier.padding(horizontal = 24.dp)
        )

        Spacer(Modifier.weight(1f))

        Spacer(Modifier.size(24.dp))
        JsTextView(
            stringResource(Res.string.web_app_in_processed),
            textSize = 20,
            textColor = JsMainTheme.colors.text_color_white,
            textAlign = TextAlign.Center,
            modifier = Modifier.padding(horizontal = 24.dp)
        )
        Spacer(Modifier.size(40.dp))

        Box(
            Modifier.fillMaxWidth().height(54.dp).padding(36.dp).clipByCorner()
                .gradientBackground(listOf(Color.rgb(0xE965C4), Color.rgb(0xA06EFC)), angle = 0)
                .clickable {
                    window.navigator.clipboard.writeText(passwordValue)
                    val webBrowserManager by di.instance<WebBrowserManager>()
                    scope.launch(Dispatchers.Main) {
                        val myAccount = accountRepository.getMyAccount()
                        val emailInfo =
                            if (myAccount?.email.isNullOrEmpty()) "" else "?email=${myAccount?.email}"
                        val resultDeepLink = "${Endpoint.getStoreDeepLink()}web-funnel$emailInfo"
                        webBrowserManager.showWebPage(resultDeepLink)
                    }
                },
            contentAlignment = Alignment.Center
        ) {
            JsTextView(
                stringResource(Res.string.web_app_download_btn),
                textSize = 18,
                fontWeight = FontWeight.Bold,
                textColor = JsMainTheme.colors.text_color_white,
                maxLines = 1,
                modifier = Modifier.padding(horizontal = 16.dp)
            )
        }
        Spacer(Modifier.size(40.dp))
    }

    if (showLoading.value) {
        Box(Modifier.fillMaxSize().background(JsMainTheme.colors.main_color_background)) {
            LoadingBlockState()
        }
    }
}