package kotpref.utils

import kotpref.models.EDialogType
import managers.ShowAlertState
import org.jetbrains.compose.resources.StringResource

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-05-04.
 */
interface IDialogManager {

    var showDialog: (ShowAlertState) -> Unit

    fun showMessageDialog(message: String)
    fun showMessageDialog(message: StringResource)

    fun showMessageWithTitleDialog(
        title: String, message: String,
        callback: () -> Unit = {}, isLastDialog: Boolean = false
    )

    fun showMessageDialog(
        mesType: EDialogType, callback: () -> Unit = {}, onCancel: () -> Unit = {},
        title: String = "", dialogText: String = "", hint: String = "",
        btnOk: String = "", btnCancel: String = ""
    )

    fun hasDialog(): Boolean

    fun haveLocationDialog(): Boolean

    fun dismissDialog()

    fun dismissStartDialogs()

    fun setNetworkSession(networkSession: Any)
    fun getNetworkSession(): Any?
    fun resetManager()

}


interface DialogCallback {
    fun onDialogClose()
    fun onDialogCancel()
}

interface DialogOkCallback : DialogCallback {
    fun onDialogOk()
    fun onDialogOk(result: String)
}

open class ADialogOkCallback : DialogOkCallback {
    override fun onDialogOk() {}
    override fun onDialogOk(result: String) {}
    override fun onDialogClose() {}
    override fun onDialogCancel() = onDialogClose()
}