@Composable
fun JsSplashScreen(
    obtainEvent: (SplashScreenEvent) -> Unit
) {
    val viewModel = rememberJsViewModel { SplashVM(obtainEvent) }

    PageContainer {
        JsImageView(
            "bg_splash_screen_web",
            modifier = Modifier.fillMaxWidth().height(resultHeight.value.px)
        )
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .minHeight(resultHeight.value.px),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Bottom
        ) {
            Column(
                modifier = Modifier.fillMaxWidth().weight(1f),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {

                Box(modifier = Modifier.weight(1f).minHeight(32.px))
                JsImageView(
                    "ic_splash_screen_logo_web",
                    modifier = Modifier.fillMaxWidth(40.percent)
                )
                JsAutoResizeText(
                    text = stringResource(Res.string.auth_start_group_logo_text),
                    modifier = Modifier
                        .fillMaxWidth(80.percent)
                        .padding(top = 48.dp, bottom = 52.dp),
                    maxTextSize = 20,
                    color = JsMainTheme.colors.text_color_default.copy(0.7f),
                    textAlign = TextAlign.Center,
                )
            }

            Column(
                modifier = Modifier.fillMaxWidth().weight(1f),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Box(modifier = Modifier.weight(1f))
                SplashFiorryButton(
                    title = stringResource(Res.string.auth_start_group_register),
                    onDoubleTap = {
                        //if (AppVariant.isWeb() && AppVariant.isDebug()) onClick(true)
                    },
                    onClick = { viewModel.continueSignUp() }
                )

                /*Box(modifier = Modifier.height(16.rem))
        SplashFiorryButton(
            title = stringResource(Res.string.auth_sign_in),
            backgroundColor = JsMainTheme.colors.text_color_default,
            withBorder = true,
            onDoubleTap = {
                //if (AppVariant.isWeb() && AppVariant.isDebug()) onClick(false)
            }
        ) { viewModel.continueSignIn() }*/

                Box(modifier = Modifier.height((resultHeight.value * 0.1).px))
                val terms = stringResource(Res.string.auth_start_group_terms)
                val privacy = stringResource(Res.string.auth_start_group_privacy)
                val fullText =
                    stringResource(
                        ResManager.appStrings.auth_start_group_full_text,
                        terms,
                        privacy
                    )

                val textColor = JsMainTheme.colors.app_main_color

                val clickableModifier = Modifier.styleModifier {
                    fontSize(clamp(6.dp, 2.vw, 11.dp))
                    color(textColor)
                    fontWeight(FontWeight.Normal)
                    whiteSpace("pre-wrap")
                    textDecorationLine(TextDecorationLine.Underline)
                    overflow(Overflow.Hidden)
                    textAlign(TextAlign.Center)
                }

                val termsModifier = clickableModifier.clickable {
                    obtainEvent(SplashScreenEvent.SettingsWebPage(Endpoint.getTermsUrl(), ""))
                }

                val privacyModifier = clickableModifier.clickable {
                    obtainEvent(
                        SplashScreenEvent.SettingsWebPage(Endpoint.getPrivacyPolicyUrl(), "")
                    )
                }

                val termsStartIndex = fullText.indexOf(terms)
                val privacyStartIndex = fullText.indexOf(privacy)
                val annotatedString = listOf(
                    AnnotatedString(fullText.substring(0, termsStartIndex), null),
                    AnnotatedString(
                        fullText.substring(termsStartIndex, termsStartIndex + terms.length),
                        termsModifier
                    ),
                    AnnotatedString(
                        fullText.substring(termsStartIndex + terms.length, privacyStartIndex),
                        null
                    ),
                    AnnotatedString(
                        fullText.substring(privacyStartIndex, privacyStartIndex + privacy.length),
                        privacyModifier
                    ),
                    AnnotatedString(
                        fullText.substring(privacyStartIndex + privacy.length), null
                    ),
                )
                JsAnnotatedStringsText(
                    annotatedStrings = annotatedString,
                    textSize = 10,
                    textColor = JsMainTheme.colors.text_color_gray,
                    modifier = Modifier
                        .fillMaxWidth(80.percent)
                        .padding(bottom = 40.dp),
                    textAlign = TextAlign.Center
                )
            }
        }
    }
}

@Composable
fun SplashFiorryButton(
    title: String,
    textColor: Color = JsMainTheme.colors.text_color_default,
    backgroundColor: Color = JsMainTheme.colors.gradient_main_button_start,
    backgroundGradientColor: Color? = JsMainTheme.colors.gradient_main_button_end,
    gradientAngle: Int = 300,
    withBorder: Boolean = false,
    buttonWidth: Int = 70,
    onDoubleTap: () -> Unit = {},
    onClick: () -> Unit,
) {
    var modifier = Modifier
        .fillMaxWidth(buttonWidth.percent)
        .height(50.dp)
        .clickable { onClick() }
        .onDoubleClick { onDoubleTap() }
        .clipByCorner(25)
    modifier = if (withBorder) {
        modifier.border(1.dp, LineStyle.Solid, color = backgroundColor)
    } else {
        if (backgroundGradientColor == null) {
            modifier.background(color = backgroundColor)
        } else {
            modifier.gradientBackground(
                listOf(backgroundColor, backgroundGradientColor),
                gradientAngle
            )
        }
    }
    Box(
        modifier = modifier,
        contentAlignment = Alignment.Center
    ) {
        JsAutoResizeText(
            text = title,
            modifier = Modifier.padding(left = 10.dp, right = 10.dp),
            color = textColor,
            maxTextSize = 16,
            fontWeight = FontWeight.Medium,
            textAlign = TextAlign.Center,
        )
    }
}