sealed class OnBoardingAgeEvent : EventVM {
    data object OnBoardingNextPage : OnBoardingAgeEvent()
    data class LocationPermission(val onAccess: (Any?) -> Unit) : OnBoardingAgeEvent()
    data class LoadPeopleSuccess(val peopleList: MutableList<Account>) : OnBoardingAgeEvent()
    data object Back : OnBoardingAgeEvent()
}

class OnBoardingAgeVM(
    private val viewModelCallback: (OnBoardingAgeEvent) -> Unit
) : ViewModel() {

    private val repositoriesProvider by di.instance<RepositoriesProvider>()
    private val deviceInfoManager by di.instance<IPlatformInfoManager>()
    private val amplitudeManager by di.instance<AmplitudeManager>()

    private val accountRepository = repositoriesProvider.accountRepository
    private val appKeys = repositoriesProvider.appKeys

    val peopleAgeText = mutableStateOf("")
    val initPage = mutableStateOf(false)
    val showingProgress = mutableStateOf(false)

    var lastMinAge = mutableStateOf(18)
    var lastMaxAge = mutableStateOf(60)
    var minValue: Int = lastMinAge.value
    var maxValue: Int = lastMaxAge.value

    /*fun obtainEvent(event: EventVM) {
        when (event) {
            is BaseEventVM.ClickSystemBack -> event.systemBack.invoke(backSystem())
            BaseEventVM.ClickBackBtn -> back()
            is BaseEventVM.ClickedBtn -> clickedBtn()

            is OnBoardingAgeEventVM.OnProgressChange -> onProgressChange(
                event.currentMin, event.currentMax
            )
        }
    }*/

    init {
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingAgePreferenceScreenShown)
        viewModelScope.launch {
            val myAccount = accountRepository.getMyAccount()
            val birthday = myAccount?.info?.birthday
            val currentDate = DateTimeConverter.getCurrentDate()
            val birthdayDate = DateTimeConverter.stringToDate(birthday) ?: currentDate
            val userAge = DateTimeConverter.periodDifference(birthdayDate, currentDate).years
            val filter = accountRepository.getMyFilter()

            if (filter == null) {
                lastMinAge.value = if (userAge - 15 < 18) 18 else setAgeValue(userAge - 15)
                minValue = lastMinAge.value

                var maxUserAge = userAge + 15
                if (maxUserAge > 50 && maxUserAge % 5 > 0) maxUserAge -= (maxUserAge % 5) + 5
                lastMaxAge.value =
                    if (maxUserAge > 95 || maxUserAge < 18) 60 else setAgeValue(maxUserAge)
                maxValue = lastMaxAge.value
            } else {
                filter.filters.age.from.let {
                    val minStartValue = setAgeValue(it)
                    lastMinAge.value = minStartValue
                    minValue = minStartValue
                }
                filter.filters.age.to.let {
                    val maxStartValue = setAgeValue(it ?: 100)
                    lastMaxAge.value = maxStartValue
                    maxValue = maxStartValue
                }
            }
            val text = "${getAgeValue(minValue)}-${getAgeValue(maxValue)}"
            peopleAgeText.value = text
            initPage.value = true
        }
    }

    fun onProgressChange(currentMin: Int, currentMax: Int) {
        if (currentMin == minValue && currentMax == maxValue) return

        val minAge = getAgeValue(currentMin)
        val maxAge = getAgeValue(currentMax)
        if (maxAge - minAge >= 4) {
            lastMinAge.value = currentMin
            lastMaxAge.value = currentMax
            peopleAgeText.value = "$minAge-$maxAge"
        } else {
            if (currentMax != lastMaxAge.value) {
                minValue = currentMin
                val step = when {
                    minAge <= 46 -> 4
                    minAge in 47..49 -> -minAge + 50 + 1
                    else -> 1
                }
                maxValue = currentMin + step
                peopleAgeText.value = "$minAge-${getAgeValue(maxValue)}"
            } else if (currentMin != lastMinAge.value) {
                minValue = currentMax - (if (maxAge <= 50) 4 else 1)
                maxValue = currentMax
                peopleAgeText.value = "${getAgeValue(minValue)}-$maxAge"
            }
        }
        AnalyticsManager.onSendEvent(AnalyticsPeopleEvents.filterChangeAge.name)
//        setAgeValue()
    }

    private fun getAgeValue(age: Int) =
        if (age >= 50) (age - 50) * 5 + 50 else age//18 + (age - 42) * 4

    private fun setAgeValue(age: Int) =
        if (age >= 50) ((age - 50) / 5 + 50) else age//42 + (age - 18) / 4

    private fun saveSelectData() {
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingAgePreferenceScreenNextClicked)
        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            val filter = accountRepository.getMyFilter() ?: AccountFilter()
            val minValue = getAgeValue(lastMinAge.value)
            filter.filters.age.from = if (minValue == 100) 95 else minValue
            filter.filters.age.to = getAgeValue(lastMaxAge.value)
            accountRepository.saveAccountFilter(filter)

            if (AppVariant.isWeb()) {
                showingProgress.value = true
                val account = accountRepository.getMyAccount()
                if (account?.measurementUnits == null) {
                    val countryCode = deviceInfoManager.getCountryCode()
                    val language = deviceInfoManager.getLanguage()
                    var measurementUnits = 1

                    if (language == Languages.ENGLISH.locale) {
                        if (countryCode == "us" || AppVariant.isFiorryOrHeaven())
                            measurementUnits = 2
                    }

                    account?.measurementUnits = measurementUnits
                }

                accountRepository.updateAccount(account, onSuccess = {
                    showingProgress.value = false
                    accountRepository.uploadFilter(filter)
                    viewModelCallback(OnBoardingAgeEvent.OnBoardingNextPage)
                    CoroutineScope(Dispatchers.Main).launch {
                        if (!it?.info?.compatibilityAnswers.isNullOrEmpty()) {
                            filter.filters.withQuestionnaire = true
                            accountRepository.saveAccountFilter(filter)
                        }
                    }
                }, onError = {
                    showingProgress.value = false
                    repositoriesProvider.dialogManager.showMessageDialog(Res.string.error_message_something_wrong)
                })
                return@launch
            }

            val showInterests = accountRepository.settingsOnboardingShowInterests()
            if (showInterests) startNextPage()
            else {
                showingProgress.value = true
                val nextPagePosition = appKeys.onboardingCurrentPage + 2
                val onboadingPages = OnBoardingPage.entries
                if (nextPagePosition < onboadingPages.size && onboadingPages[nextPagePosition] == OnBoardingPage.PHOTOS) {
                    val account = accountRepository.getMyAccount()
                    OnBoardingUpdateAccountManager(
                        routeTo = {
                            when (it) {
                                is OnBoardingUpdateAccountManagerEvent.LoadPeopleSuccess -> {
                                    viewModelCallback(OnBoardingAgeEvent.LoadPeopleSuccess(it.peopleList))
                                }

                                is OnBoardingUpdateAccountManagerEvent.LocationPermission -> {
                                    viewModelCallback(OnBoardingAgeEvent.LocationPermission(it.onAccess))
                                }

                                OnBoardingUpdateAccountManagerEvent.ShowNextPage -> viewModelCallback(
                                    OnBoardingAgeEvent.OnBoardingNextPage
                                )
                            }
                        }, repositoriesProvider.dialogManager, accountRepository
                    ) {
                        showingProgress.value = false
                    }.updateAccount(account, deviceInfoManager)
                } else startNextPage()
            }
        }
    }

    private fun startNextPage() {
        //router.route(Destination.OnBoardingNextPage())
        viewModelCallback(OnBoardingAgeEvent.OnBoardingNextPage)
    }

    private var lastClickTime = 0L

    fun clickedBtn(isDuplicate: Boolean = false) {
        val currentTime = DateTimeConverter.currentTimeMillis()
        if (currentTime - lastClickTime < 1500) return
        lastClickTime = currentTime
        if (isDuplicate) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.lookingForNextTop.name)
        else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.lookingForNextBottom.name)
        saveSelectData()
    }

    @UiThread
    fun back() {
        //router.route(Destination.Back())
        viewModelCallback(OnBoardingAgeEvent.Back)
    }

    @UiThread
    fun backSystem(): Boolean {
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingBackButtonClicked("onboarding_age_preference_screen"))
        appKeys.onboardingCurrentPage--
        return false
    }
}

sealed class OnBoardingAgeEventVM : EventVM {
    data class OnProgressChange(val currentMin: Int, val currentMax: Int) : OnBoardingAgeEventVM()
}