package kotpref.utils

import kotpref.models.SettingsEmulatorAttributes

interface IPlatformInfoManager {

    fun getPlatformType(): PlatformType

    fun getDeviceId(callback: (String) -> Unit)
    fun getDeviceId(): String
    fun getUUIDString(): String

    fun isEmulator(settingsEmulatorAttributes: SettingsEmulatorAttributes?): Boolean

    fun getAppVersion(): String
    fun getLanguage(): String

    fun sendEmail(title: String, text: String)

    fun hasInternetConnection(): Boolean
    fun gpsEnabled(): Boolean
    fun startGPSActivity()
    fun getCountryCode(): String

    fun hideStartLoader()
    fun showReCaptcha(onSuccess: (String) -> Unit, onFailure: (String?) -> Unit)
}

enum class PlatformType { Android, iOS, Web, WebAndroid, WebIOS, WebMacBook }