import kotlin.math.PI


val RotateKeyframes = Keyframes {
    from { Modifier.rotate(0.deg) }
    to { Modifier.rotate(360.deg) }
}

val DashKeyframes = CSSKeyframesBuilder().apply {
    from {
        property("stroke-dasharray", "1, 200")
        property("stroke-dashoffset", "0")
    }
    to {
        property("stroke-dasharray", "100, 200")
        property("stroke-dashoffset", "-15")
    }
}

object CircularStyles : StyleSheet() {
    init {
        keyframes { RotateKeyframes }
        keyframes { DashKeyframes }
    }
}

@Composable
fun JsCircularProgressIndicator(
    modifier: Modifier = Modifier,
    size: Int = 64,
    strokeWidth: Int = 6,
    color: Color = Colors.White
) {
    val center = size / 2
    val radius = center - strokeWidth / 2
    val circumference = 2 * PI * radius
    val rgbColor = color.toRgb()

    Style(CircularStyles)

    Svg(
        attrs = modifier
            .size(size.px)
            .animation(
                RotateKeyframes.toAnimation(
                    duration = 1.s,
                    timingFunction = AnimationTimingFunction.Linear,
                    iterationCount = AnimationIterationCount.Infinite
                )
            )
            .toAttrs {
                attr("viewBox", "0 0 $size $size")
                style {
                    property("transform-origin", "center")
                }
            }
    ) {
        Circle(
            attrs = {
                cx(center)
                cy(center)
                r(radius)
                style {
                    property("fill", "none")
                    property(
                        "stroke",
                        "rgb(${rgbColor.red}, ${rgbColor.green}, ${rgbColor.blue})"
                    )
                    property("stroke-width", strokeWidth.toString())
                    property("stroke-dasharray", "$circumference $circumference")
                    property("stroke-dashoffset", "${circumference * 0.25}")
                    //property("animation", "dash 1.5s ease-in-out infinite")
                }
            }
        )
    }
}


@Composable
fun LoadingState(color: Color = JsMainTheme.colors.app_main_color) {
    Box(Modifier.fillMaxSize().zIndex(1000)) {
        JsCircularProgressIndicator(
            modifier = Modifier.align(Alignment.Center),
            color = color
        )
    }
}


@Composable
fun LoadingBlockState() {
    Box(
        Modifier
            .fillMaxSize()
            .background(JsMainTheme.colors.main_color_black_transparent_50)
            .zIndex(1000)
            .clickable { }) {
        JsCircularProgressIndicator(
            modifier = Modifier.align(Alignment.Center),
            color = Colors.White
        )
    }
}