@Composable
fun JsSubscribeButton(
    productDetails: List<ProductDetails>,
    currentProduct: ProductDetails,
    startPrice: Double,
    isWeekFormat: Boolean,
    annual12MonthsText: Boolean,
    selectedProductID: MutableState<String>,
    isNewHorizontalDesign: Boolean,
    isNewDesign: Boolean,
    isPropose: Boolean,
    isPopular: Boolean,
    isReview: Boolean,
    btnProgress: MutableState<Boolean>,
    isBottomDrawerFragment: Boolean,
    buySubscription: (Billings, Boolean, Boolean) -> Unit,
) {
    val isUnlim = Billings.isUnlimSubscribe(currentProduct.productDetails.productId)
    val period: SubscriptionPeriod =
        Billings.getPeriodByProductId(currentProduct.productDetails.productId)
    val onSelected =
        selectedProductID.value == currentProduct.productDetails.productId || selectedProductID.value == currentProduct.discountDetails?.productId
    val periodTitle = JsSubscribeHelper.periodTitle(period, annual12MonthsText = annual12MonthsText)

    Box(
        modifier = Modifier
            .padding(top = 6.dp)
            .fillMaxWidth()
    ) {
        Box(
            modifier = Modifier
                .padding(top = 8.dp)
                .fillMaxWidth()
                .height(60.dp)
                .clipByCorner()
                .clickable {
                    JsSubscribeHelper.buySubscription(
                        productDetails = currentProduct,
                        selectedProductID = selectedProductID,
                        btnProgress = btnProgress,
                        isBottomDrawerFragment = isBottomDrawerFragment,
                        buySubscription
                    )
                },
        ) {
            SubscriptionButtonBackground(
                isNewHorizontalDesign, isNewDesign, isUnlim || isPropose, onSelected
            )

            if (btnProgress.value && selectedProductID.value == currentProduct.productDetails.productId) {
                LoadingState()
            } else if (isNewHorizontalDesign) {
                val textPrices = getTextPriceComposeNew(
                    currentProduct.productDetails,
                    currentProduct.discountDetails,
                    period,
                    startPrice,
                    isWeekFormat
                )

                JsSubscriptionButtonHorizontalContent(
                    periodTitle = periodTitle,
                    textPrices = textPrices,
                    isReview = isReview,
                    isWeekFormat = isWeekFormat,
                )
            } else {
                val textPrices = getTextPriceCompose(
                    productDetails = currentProduct.productDetails,
                    discountDetails = currentProduct.discountDetails,
                    period = period,
                    weekPrice = startPrice,
                    isWeekFormat = isWeekFormat
                )

                JsSubscriptionButtonContent(
                    periodTitle = periodTitle,
                    textPrices = textPrices,
                    isPopular = isPopular,
                    isUnlim = isUnlim || isPropose,
                    colorList = JsSubscribeHelper.gradientColors(true, isUnlim || isPropose, false),
                    onSelected = onSelected,
                    isNewDesign = isNewDesign
                )
            }
        }

        if (isPopular && isNewHorizontalDesign) JsPopularView(
            Modifier.align(Alignment.TopStart),
            productDetails, currentProduct, isUnlim || isPropose, isWeekFormat, period
        )
    }
}

@Composable
private fun JsPopularView(
    modifier: Modifier,
    productDetails: List<ProductDetails>,
    currentProduct: ProductDetails,
    isUnlim: Boolean, isWeekFormat: Boolean, period: SubscriptionPeriod
) {
    Row(modifier) {
        Box(
            modifier = Modifier
                .padding(start = 28.dp)
                .height(18.dp)
                .clipByCorner()
                .background(color = JsMainTheme.colors.btn_subscribe_unselect_color),
            contentAlignment = Alignment.Center
        ) {
            JsAutoResizeText(
                text = stringResource(Res.string.onboarding_propose_subscription_popular).uppercase(),
                modifier = Modifier
                    .clipByCorner()
                    .gradientBackground(
                        JsSubscribeHelper.gradientColors(true, isUnlim = isUnlim, true)
                    )
                    .padding(horizontal = 8.dp, vertical = 2.dp),
                maxTextSize = 10,
                minTextSize = 6,
                color = JsMainTheme.colors.text_color_default,
                fontWeight = FontWeight.ExtraBold,
                textAlign = TextAlign.Center,
                maxLines = 1
            )
        }

        if (period == SubscriptionPeriod.YEAR)
            AnnualDiscountText(productDetails, currentProduct, isUnlim, isWeekFormat)
    }
}

@Composable
private fun AnnualDiscountText(
    productDetails: List<ProductDetails>,
    currentProduct: ProductDetails,
    isUnlim: Boolean,
    isWeekFormat: Boolean
) {
    val billingManager by di.instance<IBillingManager>()
    val currentSkuDetails =
        billingManager.getSubscribePrice(currentProduct.productDetails.productId) ?: return

    val maxPriceDetails = productDetails.firstOrNull {
        if (isWeekFormat) Billings.isWeekSubscribe(it.productDetails.productId)
        else Billings.isMonthSubscribe(it.productDetails.productId)
    }
    if (maxPriceDetails == null) return
    val maxPriceSkuDetails =
        billingManager.getSubscribePrice(maxPriceDetails.productDetails.productId) ?: return

    val currentPrice = currentSkuDetails.priceAmountMicros / 1000000.0
    val maxPrice =
        (maxPriceSkuDetails.priceAmountMicros / 1000000.0) * (if (isWeekFormat) (365 / 7.0) else 12.0)
    var discountPercent = ((maxPrice - currentPrice) / maxPrice * 100.0).toInt()
    if (discountPercent % 5 > 0) discountPercent += 5 - discountPercent % 5
    if (discountPercent <= 0) return

    Box(
        modifier = Modifier
            .padding(start = 6.dp)
            .height(18.dp)
            .clipByCorner()
            .background(color = JsMainTheme.colors.btn_subscribe_unselect_color),
        contentAlignment = Alignment.Center
    ) {
        JsAutoResizeText(
            text = "-$discountPercent% ${stringResource(Res.string.onboarding_propose_subscription_discount).uppercase()}",
            modifier = Modifier
                .gradientBackground(
                    JsSubscribeHelper.gradientColors(true, isUnlim = isUnlim, true)
                )
                .padding(horizontal = 8.dp, vertical = 2.dp),
            maxTextSize = 10,
            minTextSize = 6,
            color = JsMainTheme.colors.text_color_default,
            fontWeight = FontWeight.ExtraBold,
            textAlign = TextAlign.Center,
            maxLines = 1
        )
    }
}