@kotlinx.serialization.Serializable
data class AccountFilter(
    @Transient  @SerialName("id") var id: Id = getDefaultId(),

    @Transient @SerialName("selectCity") var selectCity: String? = null,
    @Transient @SerialName("selectLat") var selectLat: Double? = null,
    @Transient @SerialName("selectLon") var selectLon: Double? = null,
    @Transient @SerialName("localLat") var localLat: Double = 0.0,
    @Transient @SerialName("localLon") var localLon: Double = 0.0,

    //@Embedded
    @SerialName("filters") var filters: AccountFilterPeople = AccountFilterPeople(),

    @SerialName("offset") var offset: Int = 0,
    @SerialName("limit") var limit: Int = 96,

    @SerialName("myGenderFreeChats") var myGenderFreeChats: Int = 0,
    @SerialName("myGenderFreeWows") var myGenderFreeWows: Int = 0,
    @SerialName("myGenderPlusChats") var myGenderPlusChats: Int = 0,
    @SerialName("myGenderPlusWows") var myGenderPlusWows: Int = 0,
    @SerialName("myGenderUnlimChats") var myGenderUnlimChats: Int = 15,

    @Transient
//    @TypeConverters(AccountFilterCityConverter::class)
    @SerialName("cities") var cities: MutableList<AccountFilterCity> = mutableListOf(),

    @Transient
//    @TypeConverters(AccountFilterWowedConverter::class)
    @SerialName("wowedUsers") var wowedUsers: MutableList<AccountFilterWowed> = mutableListOf(),

    @Transient
//    @TypeConverters(AccountFilterQuestionConverter::class)
    @SerialName("questions") var questions: MutableList<CompatibilityQuestion> = mutableListOf(),

    @SerialName("type") var type: Int = 0
)