@Composable
private fun CardInputView(
    viewModel: PaywallScreenVM, showCardInput: MutableState<Boolean>,
    stripeProduct: StripeProduct?,
    onPurchase: (String, String?, String?) -> Unit
) {
    if (showCardInput.value) Box(
        Modifier.fillMaxSize()
            .background(JsMainTheme.colors.main_color_black_transparent_50)
            .clickable { showCardInput.value = false },
        contentAlignment = Alignment.Center
    ) {
        DisposableEffect(Unit) {
            setupCardElementAndCallback(WebContainer.PaymentScreen.screenName) { paymentMethodId, errorMessage ->
                if (paymentMethodId != null) {
                    onPurchase(
                        paymentMethodId,
                        stripeProduct?.priceId,
                        stripeProduct?.productId
                    )
                } else {
                    viewModel.dialogManager.showMessageDialog(errorMessage ?: "")
                }
            }

            onDispose {
                StripeInterop.unmountCardElement()
                document.getElementById(WebContainer.PaymentScreen.screenName)?.remove()
            }
        }

        Box(
            Modifier.fillMaxWidth().padding(horizontal = 16.dp)
                .onClick { event -> event.stopPropagation() }
        ) {
            Column(
                Modifier.fillMaxWidth()
                    .padding(start = 16.dp, end = 12.dp, top = 24.dp, bottom = 16.dp)
                    .clipByCorner(24)
                    .background(JsMainTheme.colors.box_subscribe_propose_backgraund_gray)
            ) {
                Div(
                    attrs = Modifier.id(WebContainer.PaymentScreen.screenName)
                        .fillMaxWidth()
                        .padding(start = 8.dp)
                        .height(50.px)
                        .toAttrs()
                ) {

                }

                Box(
                    Modifier.fillMaxWidth().height(54.dp)
                        .padding(start = 8.dp, end = 12.dp)
                ) {
                    Box(
                        Modifier.fillMaxWidth().height(54.dp)
                            .padding(horizontal = 16.dp, vertical = 12.dp)
                            .clipByCorner()
                            .background(Color.rgb(0x056FDD))
                            .clickable {
                                StripeInterop.triggerCardPaymentMethodCreation()
                            },
                        contentAlignment = Alignment.Center
                    ) {
                        JsTextView(
                            text = "Pay",
                            textColor = JsMainTheme.colors.text_color_white,
                            textSize = 14,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun OtherPaymentInputsView(
    showOtherPayments: MutableState<Boolean>,
    stripeClientSecret: String, stripeProduct: StripeProduct?,
    onPurchase: (String, String?, String?) -> Unit
) {
    if (showOtherPayments.value) Box(
        Modifier.fillMaxSize()
            .background(JsMainTheme.colors.main_color_black_transparent_50)
            .clickable { showOtherPayments.value = false },
        contentAlignment = Alignment.Center
    ) {
        DisposableEffect(Unit) {
            StripeInterop.setupPaymentElement(
                WebContainer.PaymentScreen.screenName,
                stripeClientSecret
            )

            onDispose {
                StripeInterop.unmountCardElement()
                document.getElementById(WebContainer.PaymentScreen.screenName)?.remove()
            }
        }

        Box(
            Modifier.fillMaxWidth().padding(horizontal = 16.dp)
                .onClick { event -> event.stopPropagation() }
        ) {
            Column(
                Modifier.fillMaxWidth()
                    .padding(start = 16.dp, end = 12.dp, top = 24.dp, bottom = 16.dp)
                    .clipByCorner(24)
                    .background(JsMainTheme.colors.box_subscribe_propose_backgraund_gray)
            ) {
                Div(
                    attrs = Modifier.id(WebContainer.PaymentOtherMethods.screenName)
                        .fillMaxWidth()
                        .padding(start = 8.dp)
                        .height(200.px)
                        .toAttrs()
                ) {

                }

                Box(
                    Modifier.fillMaxWidth().height(54.dp)
                        .padding(start = 8.dp, end = 12.dp)
                ) {
                    Box(
                        Modifier.fillMaxWidth().height(54.dp)
                            .padding(horizontal = 16.dp, vertical = 12.dp)
                            .clipByCorner()
                            .background(Color.rgb(0x056FDD))
                            .clickable {
                                val returnUrl = window.location.href
                                //val returnUrl = "${window.location.origin}${window.location.pathname}"
                                StripeInterop.confirmPayment(
                                    returnUrl,
                                    true
                                ).then { result ->
                                    if (result.error != null) {
                                        showOtherPayments.value = false
                                    } else {
                                        onPurchase(
                                            stripeClientSecret,
                                            stripeProduct?.priceId,
                                            stripeProduct?.productId
                                        )
                                    }
                                }
                            },
                        contentAlignment = Alignment.Center
                    ) {
                        JsTextView(
                            text = "Pay",
                            textColor = JsMainTheme.colors.text_color_white,
                            textSize = 14,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            }
        }
    }
}

object StripeManager {

    fun setupCardElementAndCallback(
        elementId: String,
        onPaymentMethodCallback: (String?, String?) -> Unit
    ) {
        StripeInterop.setupCardElement(elementId, onPaymentMethodCallback)
    }

    suspend fun initStripePaymentRequest(
        amountInCents: Int,
        currency: String,
        countryCode: String,
        label: String
    ): PaymentRequestAvailability? {
        return try {
            StripeInterop.initializePaymentRequest(amountInCents, currency, countryCode, label)
                .await()
        } catch (e: dynamic) {
            console.error("Error initializing payment request: $e")
            null
        }
    }
}