package web.views.datePicker.picker

import androidx.compose.runtime.Composable
import androidx.compose.runtime.MutableIntState
import androidx.compose.runtime.MutableState
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import com.varabyte.kobweb.compose.foundation.layout.Box
import com.varabyte.kobweb.compose.ui.Alignment
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.modifiers.height
import com.varabyte.kobweb.compose.ui.modifiers.padding
import web.helpers.dp
import web.views.datePicker.PickerScrollState
import web.views.datePicker.getMaxDaysInMonth

@Composable
fun JsPickerScrollingDay(
    modifier: Modifier = Modifier,
    selectedDay: MutableIntState,
    selectedMonth: MutableIntState,
    selectedYear: MutableIntState,
    scrollState: MutableState<PickerScrollState>,
    rowCount: Int,
    itemHeight: Int,
    selectorProperties: SelectorProperties,
    onScrollFinished: (item: String) -> Unit,
) {
    val itemsSize = 1000
    val dayStartIndex = itemsSize / 2

    Box(
        modifier = modifier
            .height((itemHeight * rowCount).dp)
            .padding(leftRight = 8.dp),
        contentAlignment = Alignment.Center
    ) {
        JsPickerScrollingDividers(selectorProperties, rowCount)

        val currentVisibleItem = remember { mutableStateOf(dayStartIndex) }

        fun getActualDay(index: Int): Int {
            val maxDaysInMonth = getMaxDaysInMonth(selectedYear.intValue, selectedMonth.intValue)
            val selectDay = currentVisibleItem.value % maxDaysInMonth
            val diffDays = selectedDay.intValue - selectDay
            var actualDay = index + diffDays
            if (actualDay < 0) actualDay += maxDaysInMonth
            actualDay %= maxDaysInMonth
            if (actualDay == 0) actualDay = maxDaysInMonth
            return actualDay
        }

        JsLazyColumn(
            itemsSize = itemsSize,
            verticalPadding = itemHeight * ((rowCount - 1) / 2),
            currentVisibleItem = currentVisibleItem,
            startVisibleItem = dayStartIndex,
            scrollEnabled = scrollState.value == PickerScrollState.NON || scrollState.value == PickerScrollState.DAY,
            onScrollStart = { scrollState.value = PickerScrollState.DAY },
            onScrollFinished = { index ->
                scrollState.value = PickerScrollState.NON
                val actualDay = getActualDay(index)
                currentVisibleItem.value = index
                onScrollFinished(actualDay.toString())
            }
        ) { index ->
            JsPickerItem(
                text = getActualDay(index).toString(),
                index = index,
                selectIndex = currentVisibleItem.value,
                rowCount = rowCount,
                itemHeight = itemHeight
            )
        }
    }
}
