export function setupPaymentElement(elementId, clientSecret) {
    if (!stripe || !elements) {
        console.error("Stripe elements not initialized.");
        return;
    }

    const appearance = {
        theme: 'night',
    };

    const options = {
        clientSecret: clientSecret,
        appearance,
    };

    elements = stripe.elements(options);

    paymentElement = elements.create("payment", {
        layout: "tabs"
    });
    paymentElement.mount(`#${elementId}`);
    console.log("Payment Element mounted.");
}

export async function confirmPayment(returnUrl, redirectIfRequired) {
    if (!stripe || !elements) {
        return { error: "Stripe or Elements not initialized." };
    }

    const opts = {
        elements,
        confirmParams: { return_url: returnUrl }
    };

    if (redirectIfRequired) {
        opts.redirect = 'if_required';
    }

    const result = await stripe.confirmPayment(opts);

    if (result.error) {
        return { error: result.error.message || "Unknown error" };
    }
    return { error: null };
}