@Composable
fun AlertByType(
    alertType: AlertType,
    dismissOnBackPress: Boolean = false,
    dismissOnClickOutside: Boolean = false,
    withCloseButton: Boolean = false,
    onPositiveClick: () -> Unit = {},
    onNegativeClick: () -> Unit = {},
    onDismiss: () -> Unit,
) {
    val title = stringResource(alertType.getTitleResource())
    val message = stringResource(alertType.getMessageResource())
    val okButtonText = stringResource(alertType.getOkButtonResource())
    val cancelButtonText = stringResource(alertType.getCancelButtonText())
    val withCancelButton = alertType.withCancelButton()
    val showCloseButton = alertType.withCloseButton() ?: withCloseButton
    val dismissClickOutside = alertType.dismissOnClickOutside() ?: dismissOnClickOutside

    @Composable
    fun buttonsRow() {
        val cornerShape = RoundedCornerShape(6.dp)
        val buttonHeight = 42.dp

        Spacer(modifier = Modifier.height(24.dp))
        Row(
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.fillMaxWidth()
        ) {
            if (withCancelButton) {
                Box(
                    Modifier.weight(1f).height(buttonHeight).clip(cornerShape)
                        .composed {
                            if (alertType.cancelButtonWithBorder())
                                border(
                                    1.dp,
                                    alertType.getCancelButtonBackgroundColor(),
                                    cornerShape
                                )
                            else background(alertType.getCancelButtonBackgroundColor(), cornerShape)
                        }
                        .clickable {
                            onNegativeClick()
                            onDismiss()
                        }, contentAlignment = Alignment.Center
                ) {
                    TextRegular(
                        text = cancelButtonText, 14,
                        textColor = alertType.getCancelButtonTextColor(),
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier.padding(horizontal = 6.dp, vertical = 8.dp),
                        textAlign = TextAlign.Center, maxLines = 1
                    )
                }
                Spacer(modifier = Modifier.size(8.dp))
            }
            Box(
                Modifier.weight(1f).height(buttonHeight).clip(cornerShape)
                    .composed {
                        if (alertType.okButtonWithBorder())
                            border(1.dp, alertType.getOkButtonBackgroundColor(), cornerShape)
                        else background(alertType.getOkButtonBackgroundColor(), cornerShape)
                    }
                    .clickable {
                        onPositiveClick()
                        onDismiss()
                    }, contentAlignment = Alignment.Center
            ) {
                TextRegular(
                    text = okButtonText, 14,
                    textColor = alertType.getOkButtonTextColor(),
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 8.dp),
                    textAlign = TextAlign.Center, maxLines = 1
                )
            }
        }
    }

    Dialog(
        onDismissRequest = { onDismiss() }, properties = DialogProperties(
            dismissOnBackPress = dismissOnBackPress,
            dismissOnClickOutside = dismissClickOutside,
        )
    ) {
        Surface(
            modifier = Modifier.widthIn(max = webContainerMaxWidth - 32.dp).wrapContentHeight(),
            shape = RoundedCornerShape(size = 16.dp)
        ) {
            Box {
                Column(
                    modifier = Modifier.background(MainTheme.colors.main_color_background)
                        .padding(start = 16.dp, end = 16.dp, top = 16.dp, bottom = 0.dp),
                    verticalArrangement = Arrangement.Center,
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    if (title.isNotEmpty()) TextRegular(
                        text = title, 16,
                        textColor = MainTheme.colors.text_color_default,
                        fontWeight = FontWeight.Bold,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.padding(horizontal = 8.dp)
                    )
                    if (title.isNotEmpty() && message.isNotEmpty())
                        Spacer(modifier = Modifier.height(10.dp))
                    if (message.isNotEmpty()) TextRegular(
                        text = message, 14,
                        textColor = MainTheme.colors.text_color_gray,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.padding(horizontal = 8.dp)
                    )
                    buttonsRow()
                }

                if (showCloseButton) ImageView(
                    Res.drawable.ic_close_white_24dp,
                    tintColor = MainTheme.colors.app_main_color,
                    modifier = Modifier.size(16.dp).padding(16.dp).clickable { onDismiss() }
                )
            }
        }
    }
}

fun AlertType.getTitleResource(): StringResource = when (this) {
    AlertType.Logout -> Res.string.dialog_logout_title
    AlertType.DeleteAccount -> Res.string.onboarding_delete_dialog_title
    else -> Res.string.string_empty
}

fun AlertType.getMessageResource(): StringResource = when (this) {
    AlertType.DeleteAccount -> Res.string.onboarding_delete_dialog_text
    else -> Res.string.string_empty
}

fun AlertType.getOkButtonResource(): StringResource = when (this) {
    AlertType.Logout -> Res.string.nav_settings_log_out
    AlertType.DeleteAccount -> Res.string.dialog_btn_delete
    AlertType.Default -> Res.string.dialog_btn_ok
}

fun AlertType.getCancelButtonText(): StringResource = when (this) {
    else -> Res.string.btn_cancel
}

fun AlertType.withCancelButton(): Boolean = when (this) {
    AlertType.DeleteAccount -> false
    else -> true
}

fun AlertType.withCloseButton(): Boolean? = when (this) {
    AlertType.DeleteAccount -> true
    else -> null
}

fun AlertType.okButtonWithBorder(): Boolean = when (this) {
    //AlertType.Logout, AlertType.DeleteAccount -> true
    else -> false
}

fun AlertType.cancelButtonWithBorder(): Boolean = when (this) {
    AlertType.Logout, AlertType.DeleteAccount -> false
    else -> true
}

@Composable
fun AlertType.getOkButtonTextColor(): Color = when (this) {
    else -> MainTheme.colors.app_main_color
}

@Composable
fun AlertType.getOkButtonBackgroundColor(): Color = when (this) {
    else -> MainTheme.colors.main_color_background
}

@Composable
fun AlertType.getCancelButtonTextColor(): Color = when (this) {
    else -> MainTheme.colors.app_main_color
}

@Composable
fun AlertType.getCancelButtonBackgroundColor(): Color = when (this) {
    else -> MainTheme.colors.main_color_background
}

@Composable
fun AlertType.dismissOnClickOutside(): Boolean? = when (this) {
    AlertType.DeleteAccount -> true
    else -> null
}