enum class CompatibilityAnswerStatus(val value: Int) {
    NoSelect(0),
    Yes(3),
    No(1),
    Maybe(2);

    companion object {
        fun getStatus(status: Int): CompatibilityAnswerStatus {
            values().forEach {
                if (it.value == status) return it
            }
            return NoSelect
        }
    }
}