package kotpref.models.chat

import kotpref.models.account.enums.AccountVerificationStatus
import kotlinx.serialization.SerialName

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-07-05.
 */
//@Entity
@kotlinx.serialization.Serializable
class ChatUser(

    //@ColumnInfo(name = "chat_user_id")
    @SerialName("id") private val id: String,

    //@ColumnInfo(name = "chat_user_name")
    @SerialName("nickname") private val name: String,

    //@ColumnInfo(name = "chat_user_avatar")
    @SerialName("avatar") private val avatar: String? = null,

    //@ColumnInfo(name = "chat_user_online")
    @SerialName("is_online") var isOnline: Boolean,
    @SerialName("photo_verification_status") var photoVerificationStatus: String? = null,

    //@Ignore
    @SerialName("last_active_at") var lastActiveAt: String

) {

    fun getId(): String = id
    fun getName(): String = name
    fun getAvatar(): String? = avatar

    fun toLast(): LastMessageChatUser = LastMessageChatUser(id, name, avatar, isOnline)

    fun getVerificationStatus(): AccountVerificationStatus {
        //"need_verify"
        return when (photoVerificationStatus) {
            "started" -> AccountVerificationStatus.IN_PROGRESS
            "in-progress" -> AccountVerificationStatus.IN_PROGRESS
            "verified" -> AccountVerificationStatus.VERIFIED
            else -> AccountVerificationStatus.NOT_VERIFIED
        }
    }

}
