@Composable
fun JsDialogInfoGender(
    showCompatibility: Boolean,
    onDismiss: () -> Unit
) {
    Box(
        modifier = Modifier.fillMaxSize()
            .background(JsMainTheme.colors.main_color_black_transparent_30)
            .clickable { onDismiss() },
        contentAlignment = Alignment.Center
    ) {
        val showCompatibilityThis = showCompatibility || AppVariant.isEliziumOrParadiz()
        val title =
            if (!showCompatibilityThis) Res.string.people_profile_compatibility_description else
                Res.string.onboarding_compatibility_title

        val itemsTitle = getItemsInfoTitle(showCompatibilityThis)
        val itemsText = getItemsInfoText(showCompatibilityThis)

        Box(
            modifier = Modifier.fillMaxWidth(80.percent)
                .heightIn(max = (resultHeight.value * 0.6f).px)
                .clipByCorner(12)
                .background(JsMainTheme.colors.main_color_bg_2)
                .overflow(Overflow.Auto)
                .zIndex(4)
                .align(Alignment.Center)
        ) {
            Column(
                modifier = Modifier.fillMaxWidth().padding(1.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    JsTextView(
                        modifier = Modifier.weight(1f)
                            .padding(top = 12.dp, start = 10.dp, bottom = 12.dp),
                        text = stringResource(title),
                        textColor = JsMainTheme.colors.text_color_default,
                        fontWeight = FontWeight.Bold,
                        textSize = 18,
                        textAlign = TextAlign.Center
                    )

                    Box(Modifier.clickable { onDismiss() }.padding(all = 10.dp)) {
                        JsImageView(Res.drawable.ic_close_white_24dp, modifier = Modifier.size(24.dp))
                    }
                }

                Spacer(
                    modifier = Modifier.height(1.dp).fillMaxWidth()
                        .background(color = JsMainTheme.colors.text_color_hint)
                )

                Column(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    repeat(itemsTitle.size) {
                        JsInfoGenderItem(
                            title = stringResource(itemsTitle[it]),
                            text = stringResource(itemsText[it])
                        )
                    }
                    Spacer(modifier = Modifier.height(16.dp))
                }
            }
        }
    }
}

@Composable
private fun getItemsInfoTitle(showCompatibility: Boolean) =
    if (showCompatibility) descriptionCompatibilityTitles()
    else if (AppVariant.isHeaven()) onboardingGenderTitlesListHeaven()
    else onboardingGenderTitlesList()

@Composable
private fun getItemsInfoText(showCompatibility: Boolean) =
    if (showCompatibility) descriptionCompatibilityText()
    else if (AppVariant.isHeaven()) onboardingGenderTextListHeaven()
    else onboardingGenderTextList()