sealed class OnBoardingStartEvent : EventVM {
    data object ShowMainPage : OnBoardingStartEvent()
    data object OnBoardingGenderInfo : OnBoardingStartEvent()
    data object OnBoardingNextPage : OnBoardingStartEvent()
    data object Back : OnBoardingStartEvent()
    data class ClearData(val reason: String) : OnBoardingStartEvent()
}

class OnBoardingStartVM(
    val startPage: Boolean,
    private val viewModelCallback: (OnBoardingStartEvent) -> Unit
) : ViewModel() {

    private val repositoriesProvider by di.instance<RepositoriesProvider>()
    private val dialogManager by di.instance<IDialogManager>()
    private val billingManager by di.instance<IBillingManager>()
    private val adaptyManager by di.instance<AdaptyManager>()
    private val amplitudeManager by di.instance<AmplitudeManager>()

    private val accountRepository = repositoriesProvider.accountRepository
    private val appKeys = repositoriesProvider.appKeys

    var alpha = mutableFloatStateOf(0.3f)

    val loading = mutableStateOf(false)
    private var multiSelectList = mutableStateListOf<MultiSelectItem>()
    private val _multiSelectListFlow = MutableStateFlow(multiSelectList)
    val multiSelectListFlow: StateFlow<List<MultiSelectItem>> get() = _multiSelectListFlow
    private var selectItems = false

    val showGenderInfoDialog = mutableStateOf(false)

    /*fun obtainEvent(event: EventVM) {
        when (event) {
            is BaseEventVM.ClickSystemBack -> event.systemBack.invoke(backSystem())
            is BaseEventVM.ClickedBtn -> clickedBtn(event.isDuplicate)
            BaseEventVM.ClickBackBtn -> back()

            OnBoardingStartEventVM.InfoBtnClick -> infoBtnClick()
            is OnBoardingStartEventVM.SetSelectItem -> setSelectItem(event.item)
            OnBoardingStartEventVM.RefreshTokenEvent -> refreshTokenEvent()
            is OnBoardingStartEventVM.ClearData -> clearData(event.reason)
        }
    }*/

    init {
        if (startPage) initBillingManager()

        if (AppVariant.isWeb()) billingManager.getAllProductDetails {}

        appKeys.onboardingCompatibilityAnswers = false
        if (startPage) {
            accountRepository.loadSettings()
            if (!appKeys.startOnboarding) {
                appKeys.startOnboarding = true
                AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.onboardingStart.name)
                AnalyticsManager.onSendAppsFlyerEvent("onboarding_start")
                amplitudeManager.sendEvent(AmplitudeEvent.OnboardingYourGenderScreenShown)
            }
            if (!appKeys.webSendAnalytics) {
                appKeys.webSendAnalytics = true
                val trafficSource = appKeys.webTrafficSource
                if (trafficSource.isNotEmpty()) {
                    val pageName = appKeys.webPageName
                    amplitudeManager.sendIdentify("traffic_source", trafficSource)
                    amplitudeManager.sendIdentify("page_name", pageName)
                    amplitudeManager.sendEvent(AmplitudeEvent.WebDownload(trafficSource, pageName))
                }
            }
        } else {
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingPartnerGenderScreenShown)
        }

        if (AppVariant.isEliziumOrParadiz()) {
            if (appKeys.userLogin.isEmpty()) {
                accountRepository.loadMe()
            }
        }
        viewModelScope.launch(Dispatchers.Main) {
            AccountIam.sortList().forEach {
                val value = if (startPage) it.resId() else it.secondResId()
                multiSelectList.add(MultiSelectItem(value.getString()))
            }

            suspend fun setSelectData(myAccount: Account?) {
                if (startPage && (myAccount?.info?.iamList?.size ?: 0) >= 2) return
                val list =
                    if (startPage) myAccount?.info?.iamList else myAccount?.info?.interestedIn

                list?.forEach { item ->
                    val iam = AccountIam.sortList().firstOrNull { it.position == item }
                    if (iam != null) {
                        val value = if (startPage) iam.resId() else iam.secondResId()
                        val multiSelectItem = MultiSelectItem(itemTitle = value.getString())
                        val index = multiSelectList.indexOf(multiSelectItem)
                        multiSelectList[index] = multiSelectList[index].copy(onSelected = true)
                        alpha.floatValue = if (multiSelectList.any { it.onSelected }) 1f else 0.3f
                    }
                }
            }

            suspend fun setSelectDataByCurrentPage() {
                val currentPage = appKeys.onboardingCurrentPage
                val pagePosition =
                    if (startPage) OnBoardingPage.START.ordinal
                    else OnBoardingPage.INTEREST.ordinal

                if (pagePosition <= currentPage) {
                    val myAccount = accountRepository.getMyAccount()
                    setSelectData(myAccount)
                } else {
                    appKeys.onboardingCurrentPage = pagePosition
                }
            }

            if (AppVariant.isFiorryOrHeaven()) {
                if (startPage) setSelectDataByCurrentPage()
                else {
                    val myAccount = accountRepository.getMyAccount()
                    if (!myAccount?.info?.interestedIn.isNullOrEmpty()) setSelectData(myAccount)
                    else setSelectDataByCurrentPage()
                }
            } else {
                val myAccount = accountRepository.getMyAccount()
                setSelectData(myAccount)
            }
        }
    }

    private fun saveSelectData() {
        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            val data = mutableListOf<AccountIam>()
            multiSelectList.forEach {
                AccountIam.sortList().forEach { enum ->
                    val identity = if (startPage) enum.resId() else enum.secondResId()
                    if (identity.getString() == it.itemTitle && it.onSelected) data.add(enum)
                }
            }
            if (appKeys.userRegistered) {
                val account = Account("", accountRepository.getAppKeys().userLogin)
                account.info.iamList = AccountIamConverter.listToPositions(data)
                loading.value = true
                accountRepository.updateAccount(account, onSuccess = {
                    //router.route(Destination.MainStart())
                    viewModelCallback(OnBoardingStartEvent.ShowMainPage)
                    loading.value = false
                }, onError = { loading.value = false })
            } else {
                var account = accountRepository.getMyAccount()
                if (account == null) account = Account(
                    "", accountRepository.getAppKeys().userLogin
                )
                val genders = AccountIamConverter.listToPositions(data)
                if (startPage) account.info.iamList = genders
                else account.info.interestedIn = genders
                sendEventGenders(account)
                accountRepository.saveMyAccount(account)
                startNextPage(account)
            }
        }
    }

    fun infoBtnClick() {
        if (startPage) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.buttonQuestionGendersIdentity.name)
        else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.buttonQuestionGendersLooking.name)
        showGenderInfoDialog.value = true
        //router.route(Destination.OnBoardingGenderInfo())
        //viewModelCallback(OnBoardingStartEvent.OnBoardingGenderInfo)
    }

    fun setSelectItem(item: MultiSelectItem) {
        val index = multiSelectList.indexOf(item)
        if (startPage && !item.onSelected) {
            for (i in multiSelectList.indices) {
                multiSelectList[i] = multiSelectList[i].copy(onSelected = i == index)
            }
        } else multiSelectList[index] = multiSelectList[index].copy(onSelected = !item.onSelected)
        alpha.floatValue = if (multiSelectList.any { it.onSelected }) 1f else 0.3f
    }

    private fun sendEventGenders(account: Account) {
        val list = (if (startPage) account.info.iamList else account.info.interestedIn) ?: return
        val gendersList = mutableListOf<AccountIam>()
        for (i in AccountIam.sortList().toTypedArray().indices) {
            if (list.contains(AccountIam.sortList()[i].position)) {
                if (startPage) AnalyticsManager.onSendEvent(AnalyticsRegistrationGenderEvents.entries[i].name)
                else AnalyticsManager.onSendEvent(AnalyticsRegistrationLookingForEvents.entries[i].name)
                gendersList.add(AccountIam.sortList()[i])
            }
        }
        if (startPage) {
            adaptyManager.updateProfile(account, onFinish = {
                appKeys.userSendInfoToAdapty = true
                accountRepository.loadPaywalls(PaywallType.Paywall)
            })
            AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.genderIdentificationCount.name)
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingYourGenderScreenNextClicked)

            val amplitudeGender = gendersList.first()
            val gender = AmplitudeAccountGender.getGenderByAccountIAmPosition(amplitudeGender)
            amplitudeManager.sendIdentify("gender", gender.name)
        } else {
            AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.genderLookingForCount.name)
            val amplitudeGenders = gendersList.map {
                AmplitudeAccountGender.getGenderByAccountIAmPosition(it)
            }
            amplitudeManager.sendEvent(
                AmplitudeEvent.OnboardingPartnerGenderScreenNextClicked(
                    amplitudeGenders
                )
            )
        }
    }

    private fun startNextPage(account: Account) {
        val shortOnboarding = accountRepository.isShortOnboardingFlow()
        if (shortOnboarding && !startPage) {
            loading.value = true
            accountRepository.loadMe(
                onSuccess = {
                    accountRepository.updateAccount(account, onSuccess = {
                        //router.route(Destination.MainStart())
                        viewModelCallback(OnBoardingStartEvent.ShowMainPage)
                        loading.value = false
                    }, onError = { loading.value = false })
                }, onError = {
                    loading.value = false
                }
            )
        } /*else if(AppVariant.isWeb() && !startPage) {
            loading.value = true
            accountRepository.updateAccount(account, onSuccess = {
                viewModelCallback(OnBoardingStartEvent.OnBoardingNextPage)
                loading.value = false
            }, onError = { loading.value = false })
        }*/ else {
            //router.route(Destination.OnBoardingNextPage())
            viewModelCallback(OnBoardingStartEvent.OnBoardingNextPage)
        }
    }

    private var lastClickTime = 0L

    fun clickedBtn(isDuplicate: Boolean) {
        val currentTime = DateTimeConverter.currentTimeMillis()
        if (currentTime - lastClickTime < 1500) return
        lastClickTime = currentTime

        val hasInternet = accountRepository.platformInfoManager.hasInternetConnection()
        if (!hasInternet) {
            viewModelScope.launch(Dispatchers.Main) {
                val message: String =
                    ResManager.getString(Res.string.onboarding_error_internet_dialog_text)
                dialogManager.showMessageDialog(message)
            }
            return
        }

        if (multiSelectList.any { it.onSelected }) {
            if (startPage) {
                if (isDuplicate) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.identityNextTop.name)
                else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.identityNextBottom.name)
            } else {
                if (isDuplicate) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.lookingNextTop.name)
                else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.lookingNextBottom.name)
            }
            saveSelectData()
        } else {
            viewModelScope.launch(Dispatchers.Main) {
                val message: String = ResManager.getString(Res.string.onboarding_error_dialog_text)
                dialogManager.showMessageDialog(message)
            }
        }
    }

    @UiThread
    fun back() {
        if (startPage) backSystem()
        else {
            //router.route(Destination.Back())
            viewModelCallback(OnBoardingStartEvent.Back)
        }
    }

    @UiThread
    fun backSystem(): Boolean {
        fun okDialogClick() {
            AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.deleteAccountChooseGender.name)
            loading.value = true
            viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
                val account = accountRepository.getMyAccount()
                sendDeleteLog(account)
                accountRepository.deleteAccount(onSuccess = {
                    amplitudeManager.sendEvent(
                        AmplitudeEvent.UserDeleteAccount(
                            account?.accountId, account?.uuid, account?.profileId,
                            "select_your_gender", 1
                        )
                    )
                    accountRepository.getAppKeys().userBirthday = 0L
                    //router.route(Destination.ClearData("delete_acc_from_select_your_gender"))
                    clearData("delete_acc_from_select_your_gender")
                    loading.value = false
                }, onError = {
                    viewModelScope.launch(Dispatchers.Main) {
                        loading.value = false
                        val title =
                            ResManager.getString(Res.string.nav_account_delete_error_title)
                        val text =
                            ResManager.getString(Res.string.nav_account_delete_error_text)
                        if (AppVariant.isWeb()) {
                            dialogManager.showDialog(ShowAlertState.ShowDefaultDialog(title, text))
                        } else dialogManager.showMessageDialog(
                            mesType = EDialogType.DIALOG_WITH_TEXT,
                            title = title, dialogText = text
                        )
                    }
                }, reason = 1)
            }
        }

        return if (startPage) {
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingCancelButtonClicked)
            dialogManager.showMessageDialog(
                mesType = EDialogType.DIALOG_DELETE_ACCOUNT_ONBOARDING,
                callback = ::okDialogClick
            )
            true
        } else {
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingBackButtonClicked("onboarding_partner_gender_screen"))
            appKeys.onboardingCurrentPage--
            false
        }
    }

    private fun sendDeleteLog(account: Account?) {
        val authProvider = account?.login ?: ""
        val email = account?.email ?: ""
        val message = "auth_provider_id = $authProvider; email = $email"
        accountRepository.loggedError(ScreenEnum.DeleteAccountOnboarding, message)
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingCancelConfirmButtonClicked)

    }

    fun refreshTokenEvent() {
        if (startPage) accountRepository.refreshToken()
    }

    fun initBillingManager() {
        billingManager.startConnection()
    }

    fun clearData(reason: String) {
        if (AppVariant.isWeb()) {
            appKeys.startOnboarding = false
            repositoriesProvider.database.clearDatabase()
        }
        //router.route(Destination.ClearData("delete_acc_from_select_your_gender_error_$reason"))
        viewModelCallback(OnBoardingStartEvent.ClearData("delete_acc_from_select_your_gender_error_$reason"))
    }
}