sealed class OnBoardingFinishEvent {
    data class LocationAccess(val onAccess: (Any?) -> Unit) : OnBoardingFinishEvent()
    data class GpsAccess(val onAccess: (Any?) -> Unit) : OnBoardingFinishEvent()
    data object SubscribePropose : OnBoardingFinishEvent()
    data object OnBoardingNextPage : OnBoardingFinishEvent()
    data object OnBoardingTutorial : OnBoardingFinishEvent()
    data object SplashStart : OnBoardingFinishEvent()
    data class LoadPeopleSuccess(val peopleList: MutableList<Account>) : OnBoardingFinishEvent()
    data class ShowMainPage(val clearBackStack: Boolean = false) : OnBoardingFinishEvent()
}

class OnBoardingFinishVM(
    private val viewModelCallback: (OnBoardingFinishEvent) -> Unit
) : ViewModel() {

    val firebaseManager by di.instance<IFirebaseManager>()
    val repositoriesProvider by di.instance<RepositoriesProvider>()
    val billingManager by di.instance<IBillingManager>()
    private val amplitudeManager by di.instance<AmplitudeManager>()
    private val platformInfoManager: IPlatformInfoManager by di.instance()

    private val dialogManager = repositoriesProvider.dialogManager
    private val appKeys = repositoriesProvider.appKeys
    private val accountRepository = repositoriesProvider.accountRepository
    private val chatRepository = repositoriesProvider.chatRepository

    private var myAccount: Account? = null

    var mainTitle =
        if (appKeys.onboardingCompatibilityAnswers) Res.string.onboarding_finish_title_with_compatibility
        else Res.string.onboarding_finish_title
    var text =
        if (appKeys.onboardingCompatibilityAnswers) Res.string.onboarding_finish_text_with_compatibility
        else Res.string.onboarding_finish_text

    init {
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingAccountCreatedScreenShown)
        if (!accountRepository.isShortOnboardingFlow())
            appKeys.onboardingCurrentPage = OnBoardingPage.FINISH.ordinal
        appKeys.onboardingCurrentPage = OnBoardingPage.FINISH.ordinal
        checkLocation()

        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            myAccount = accountRepository.getMyAccount()
            val filter = accountRepository.getMyFilter() ?: AccountFilter()
            loadPeopleIfCan(myAccount, filter)

            appKeys.onboardingCompatibilityAnswers =
                !myAccount?.info?.compatibilityAnswers.isNullOrEmpty()
        }
    }

    fun getPageBackgroundImage(): DrawableResource {
        return if (appKeys.onboardingCompatibilityAnswers) {
            Res.drawable.bg_finish_page_with_compatibility
        } else {
            Res.drawable.bg_finish_page
        }
    }

    private fun checkLocation(startPage: Boolean = true) {
        viewModelCallback(OnBoardingFinishEvent.LocationAccess {
            if (it == null) {
                AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.denyLocation.name)
                return@LocationAccess
            }
            AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.allowLocationAlwaysInUse.name)
            if (!startPage) showNextPage()
        })
    }

    fun clickedBtn() {
        val hasInternet = accountRepository.platformInfoManager.hasInternetConnection()
        if (!hasInternet) {
            viewModelScope.launch(Dispatchers.Main) {
                val message =
                    ResManager.getString(Res.string.onboarding_error_internet_dialog_text)
                dialogManager.showMessageDialog(message)
            }
            return
        }
        showNextPage()
    }

    private fun showNextPage(acc: Account? = null) {
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingAccountCreatedScreenContinueClicked)
        if (accountRepository.isShortOnboardingFlow() || AppVariant.isWeb()) {
            //router.route(Destination.OnBoardingNextPage())
            viewModelCallback(OnBoardingFinishEvent.OnBoardingNextPage)
            return
        }

        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            val account = acc ?: accountRepository.getMyAccount()
            if (account != null) updateAcc(acc, account)
        }
    }

    private fun updateAcc(acc: Account?, account: Account) {
        when {
            account.info.iamList?.size == 0 -> {
                viewModelScope.launch(Dispatchers.Main) {
                    val text = ResManager.getString(Res.string.onboarding_finish_my_gender_error)
                    dialogManager.showMessageDialog(text)
                    accountRepository.getAppKeys().onboardingCurrentPage =
                        OnBoardingPage.START.ordinal
                    //router.route(Destination.SplashStart())
                    viewModelCallback(OnBoardingFinishEvent.SplashStart)
                }
            }

            account.info.interestedIn?.size == 0 -> {
                viewModelScope.launch(Dispatchers.Main) {
                    val text =
                        ResManager.getString(Res.string.onboarding_finish_interested_gender_error)
                    dialogManager.showMessageDialog(text)
                    accountRepository.getAppKeys().onboardingCurrentPage =
                        OnBoardingPage.INTEREST.ordinal
                    //router.route(Destination.SplashStart())
                    viewModelCallback(OnBoardingFinishEvent.SplashStart)
                }
            }

            else -> {
                val accountParams = Account()
                accountParams.id = account.id
                accountParams.info = account.info
                val onboardingWithBirthday = accountRepository.getAppKeys().onboardingWithBirthday
                if (!onboardingWithBirthday || account.birthdayIsEdited == true) {
                    accountParams.info.birthday = null
                }
                accountRepository.getAppKeys().onboardingWithBirthday = false

                appKeys.registrationByFacebook = false
                repositoriesProvider.setStartValues()
                firebaseManager.init()
                //chatRepository.connectWebSocket(platformInfoManager.getAppVersion())
                if (accountRepository.settingsOnboardingType() == 1) {
                    //router.route(Destination.OnBoardingTutorial())
                    viewModelCallback(OnBoardingFinishEvent.OnBoardingTutorial)
                } else {
                    accountRepository.loadSettings({
                        if (AppsFlyerManagerData.needShowVoucherPage) {
                            accountRepository.getAppKeys().userRegistered = true
                            //router.route(Destination.MainStart(true))
                            viewModelCallback(OnBoardingFinishEvent.ShowMainPage(true))
                        } else showProposePageIfNeed()
                    })
                }
            }
        }
    }

    private fun showProposePageIfNeed() {
        val paywallType = accountRepository.settingsPaywallType()
        val paywallStyle =
            accountRepository.userAdaptyPaywalls.adaptyPaywallConfig?.getPaywallStyle() ?: 1
        billingManager.getPurchaseDetails(callback = {
            viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
                val productId = billingManager.getProductId(it) ?: ""
                val myGender = accountRepository.getMyAccount()?.info?.iamList?.firstOrNull()
                if (paywallType == 0 || productId.isNotEmpty() || (paywallType in 13..14 && myGender == AccountIam.W.position) || paywallStyle == 0) {
                    accountRepository.getAppKeys().userRegistered = true
                    //router.route(Destination.MainStart())
                    viewModelCallback(OnBoardingFinishEvent.ShowMainPage())
                } else if (paywallType == 3 || paywallType == 6 || paywallType == 8) {
                    billingManager.getPurchaseHistory(callback = { history ->
                        val boughtTrial = billingManager.usedFreeTrial(history)
                        if (boughtTrial) {
                            accountRepository.getAppKeys().userRegistered = true
                            //router.route(Destination.MainStart())
                            viewModelCallback(OnBoardingFinishEvent.ShowMainPage())
                        } else {
                            //router.route(Destination.SubscribePropose(OpenProposeFromPage.FinalOnboarding.name))
                            viewModelCallback(OnBoardingFinishEvent.SubscribePropose)
                        }
                    })
                } else {
                    //router.route(Destination.SubscribePropose(OpenProposeFromPage.FinalOnboarding.name))
                    viewModelCallback(OnBoardingFinishEvent.SubscribePropose)
                }
            }
        })
    }

    private fun loadPeopleIfCan(myAccount: Account?, filter: AccountFilter) {
        viewModelCallback(OnBoardingFinishEvent.GpsAccess(
            onAccess = {
                if (!accountRepository.isShortOnboardingFlow() && !AppVariant.isWeb()) {
                    //router.route(Destination.OnBoardingNextPage())
                    viewModelCallback(OnBoardingFinishEvent.OnBoardingNextPage)
                }
                if (it == null) return@GpsAccess
                val lat = accountRepository.locationUtils.lastLat
                val lon = accountRepository.locationUtils.lastLon
                if (lat != 0.0 && lon != 0.0) {
                    filter.localLat = lat
                    filter.localLon = lon
                    viewModelScope.launch(Dispatchers.Main) { /* runBlocking */ accountRepository.saveAccountFilter(
                        filter
                    )
                    }

                    accountRepository.updateUserCity(lat, lon, onSuccess = {
                        loadPeople(myAccount, filter)
                    })
                }
            }
        ))
    }

    private fun loadPeople(myAccount: Account?, filter: AccountFilter) {
        val limit = when (myAccount?.subscriptionStatus?.subscription?.type ?: 0) {
            2 -> 96
            1 -> 500
            else -> 150
        }
        accountRepository.loadAccountsByFilter(filter, 0, limit, onSuccess = {
            viewModelCallback(OnBoardingFinishEvent.LoadPeopleSuccess(it ?: mutableListOf()))
        })
    }

    @UiThread
    fun backSystem(): Boolean {
        return true
    }
}
